window.__LEX={"G100":"<h1>hadrotes</h1>\n<p>Strong n° 100 <i>Prononciation [had-rot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>grande abondance, collection importante, forte somme</li>\n<li>épaisseur, plénitude, vigueur d'où largesse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἁδροτής</b> <b>ῆτος (ἡ)</b> force, vigueur, IL. <i>16, 857 (seul acc</i>. -ῆτα ; <i>conj</i>. ἀνδροτῆτα) ; <i>en parl. de plantes,</i> TH. <i>H.P. 7, 4, 11 ; p. anal. en parl. du son,</i> AMARANT. (ATH. <i>415</i> a).<p><b>Étym</b>. ἁδρός.<b>ἁδρότης</b> <b>ήτος (ἡ)</b> abondance, NT. <i>2Cor. 8, 20</i>.</p><p><b>Étym</b>. ἁδρός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδροτνς - ἁδρότης</font>\n<br><br>vient de hadros (grosse)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1) => <a class=\"ref\" data-r=\"2CO8.20\">2 Corinthiens 8.20</a></li>\n</ul>\n</td></tr>\n</table>","G101":"<h1>adunateo</h1>\n<p>Strong n° 101 <i>Prononciation [ad-oo-nat-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>impossible\n<ol type=\"a\">\n<li>ne pas avoir de force, de puissance, de talent, être faible</li>\n<li>ne peut être fait, être impossible</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀδυνατέω</b> <b>ἀδυνατέω-ῶ</b> <font color=\"brown\">[ᾰῠᾰ]</font> :<br><b> 1</b> être impuissant, ne pouvoir pas, PLAT. <i>Rsp. 366</i> d ; ARSTT. <i>Somn. 1, 8, etc. ; avec l’inf</i>. être incapable de, XÉN. <i>Mem. 1, 2, 23 ;</i> ARSTT. <i>Nic. 10, 4, 9, etc. ;</i><br><b> 2</b> impers. ἀδυνατεῖ, il est impossible de, NT. <i>Matth. 17, 20 ; Luc. 1, 37</i>.<p><b>Étym</b>. ἀδύνατος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδυνατεω - ἀδυνατέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT17.20\">Matthieu 17.20</a></li>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK1.37\">Luc 1.37</a></li>\n</ul>\n</td></tr>\n</table>","G102":"<h1>adunatos</h1>\n<p>Strong n° 102 <i>Prononciation [ad-oo'-nat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>Sens physique : sans force, impotent, impuissant, faible, invalide Sens moral :</li>\n<li>incapable d'être fait, impossible, faible,</li>\n<li>Substantif : Ce qui est impossible</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀδύνατος</b> <b>ος, ον</b> <font color=\"brown\">[ᾰῠᾰ]</font> :<br><b> 1</b> impuissant, faible : ἀδ. σώματι, LYS. <i>197, 26,</i> invalide ; οἱ ἀδ. ESCHN. <i>14, 40,</i> les invalides, <i>càd. les citoyens que des blessures ou des infirmités naturelles rendaient impropres à soutenir leur vie ;</i> ἀδ. νέες, HDT. <i>6, 16,</i> navires hors de service ; ἀδ. χρήμασι, THC. <i>7, 18,</i> pauvre ; <i>avec l’inf</i>. impuissant <i>ou</i> impropre à, incapable de, HDT. <i>3, 138 ;</i> THC. <i>1, 73 ;</i> EUR. <i>H.f. 56 ;</i> ARSTT. <i>Rhet. 2, 2, 7, etc. ;</i> εἴς τι, PLAT. <i>Hipp. mi. 366</i> b ; κατά τι, ATH. <i>1</i> f ; τι, ATT. impuissant à faire qqe ch., impropre à qqe ch. ; <i>abs</i>. incapable, EUR. <i>I.A. 369 ;</i><br><b> 2</b> impossible : τὸ ἀδ. HDT. <i>9, 60 ;</i> ATT. ; τὰ ἀδ. ATT. l’impossible ; τὰ ἀδ. καρτερεῖν, EUR. <i>I.A. 1370,</i> s’obstiner à faire l’impossible ; ἀδύνατόν ἐστι, HDT. <i>1, 32 ;</i> ἀδύνατά ἐστι, HDT. <i>1, 91, etc. ;</i> THC. <i>2, 74, etc</i>. il est impossible de, <i>inf. ;</i> ἀδύνατόν τινι ὥστε, PLAT. <i>Prot. 338</i> c, <i>m. sign</i>.<br><i>● Cp</i>. -ώτερος, THC. <i>3, 37 ;</i> XÉN. <i>Mem. 2, 65, etc. ;</i> PLAT. <i>Gorg. 483</i> d, <i>etc.</i> <i>● Sup</i>. -ώτατος, XÉN. <i>Hell. 6, 4, 11 ;</i> PLAT. <i>Phil. 15</i> b, <i>etc. ;</i> EUP. <i>2-1, 461 Meineke</i>.<p><b>➼</b> <i>Rare en poés. ; parmi les Trag. seul</i>. EUR. <i>H.f. 56, Andr. 746, etc</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδυνατος - ἀδύνατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT19.26\">Matthieu 19.26</a></li>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK10.27\">Marc 10.27</a></li>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK18.27\">Luc 18.27</a></li>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT14.8\">Actes 14.8</a></li>\n<li>Romains (2) => <a class=\"ref\" data-r=\"ROM8.3;15.1\">Romains 8.3 ; 15.1</a></li>\n<li>Hébreux (4) => <a class=\"ref\" data-r=\"HEB6.4,18;10.4;11.6\">Hébreux 6.4,18 ; 10.4 ; 11.6</a></li>\n</ul>\n</td></tr>\n</table>","G103":"<h1>ado</h1>\n<p>Strong n° 103 <i>Prononciation [ad'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>louange de quelqu'un, chanter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ᾄδω</b> <font color=\"brown\">[ᾱͅ]</font> <i>contr. att. de</i> ἀείδω, <i>v. ci-dessous <font color=\"darkgreen\">(impf</font></i><font color=\"darkgreen\">. ᾖδον, <i>f</i>. ᾄσομαι, <i>rar</i>. ᾄσω ; <i>ao</i>. ᾖσα : <i>pf. inus. ; pass. ao</i>. ᾔσθην, <i>pf. réc</i>. ᾖσμαι)</font><br><b> 1</b> chanter, <i>abs., en parl. du chant des Muses,</i> IL. <i>1, 604, etc. ; du chant des oiseaux,</i> THCR. <i>Idyl. 7, 141 ;</i> EL. <i>N.A. 6, 19 ; du chant du coq,</i> PLAT. <i>Conv. 223, etc. ; p. ext. de divers bruits (arc que l’on tend,</i> OD. <i>21, 411 ; sifflement du vent à travers un arbre,</i> MOSCH. <i>5, 8 ; pierre lancée avec force,</i> THCR. <i>Idyl. 7, 26) etc. ;</i> ἀείδειν τινί, chanter pour qqn, OD. <i>22, 346 ; ou</i> chanter contre qqn, <i>càd</i>. disputer à qqn le prix du chant, THCR. <i>Idyl. 8, 6 ; ou</i> chanter en l’honneur de qqn ; ᾄδ. εἴς τινα, AR. <i>Lys. 1243,</i> chanter les louanges de qqn ; ἀείδειν ἀμφί τινος, OD. <i>8, 267,</i> chanter <i>ou</i> célébrer qqe ch. ; ᾄδ. πρὸς αὐλὸν ἢ λύραν, ARSTT. <i>Probl. 19, 9. ou</i> ὑπ' αὐλόν, PLUT. <i>M. 41</i> c, chanter en s’accompagnant de la flûte <i>ou</i> de la lyre ; <i>avec un acc</i>. παιήονα, IL. <i>1, 473,</i> chanter un péan ;<br><b> 2</b> chanter, célébrer : τι, IL. <i>1, 1 ;</i> OD. <i>1, 326 ; etc</i>. qqe ch. ;<br><b> 3</b> chanter comme un refrain, avoir toujours à la bouche, PLAT. <i>Lys. 203</i> c ; LUC. <i>Somn. 12 ;</i><br><b> 4</b> faire résonner de ses chants, <i>d’où, au pass.,</i> ἀείδετο πᾶν τέμενος θαλίαις, PD. <i>P. 11, 79,</i> tout le temple résonnait de chants.<p><b>➼<br>   I</b> <i>Formes particul. Fut</i>. ᾄσω, <i>réc</i>. BABR. <i>12, 18 ;</i> HIM. <i>Or. 1, 6, etc. ; en prose att</i>. PLAT. <i>Leg. 666</i> d <i>dout. ; dor</i>. ᾀσῶ, THCR. <i>Idyl. 1, 145 ; f. moy. dor</i>. ᾀσεῦμαι, THCR. <i>Idyl. 3, 38 ; pf. pass</i>. ᾖσμαι, COM. <i>fr. 2, 638 ;</i> PHILSTR. <i>V. Ap. 1, 39 ;</i> HIM. <i>Or. 16, 2 ;</i> ARSTD. <i>5, 36 ;</i><br><b>   II</b> <i>Verbe épq. et poét</i>. ἀείδω (<i>impf</i>. ἤειδον, <i>f</i>. ἀείσω <i>ou</i> ἀείσομαι ; <i>ao</i>. ἤεισα ; <i>pf. inus.). Formes particul. : prés. 3 sg. sbj. épq</i>. ἀείδῃσι, OD. <i>19, 519 ; inf. épq</i>. ἀειδέμεναι, OD. <i>8, 73, ou</i> ἀειδέμεν, THGN. <i>939 ; inf. lac</i>. ἀείδην, ALCM. <i>57, ou</i> ἀεῖδεν, ALCM. <i>1, 3 ;</i> THCR. <i>Idyl. 7, 100. Impf</i>. ἄειδον <font color=\"brown\">[ᾰ]</font> IL. <i>1, 604 ;</i> PD. <i>N. 5, 22 ;</i> THCR. <i>Idyl. 8, 29 ;</i> ἄειδον <font color=\"brown\">[ᾱ <i>à l’arsis</i>]</font> OD. <i>17, 519 ;</i> HH. <i>18, 1 ;</i> THCR. <i>Idyl. 18, 7. Ao</i>. ἄεισα <font color=\"brown\">[ᾱει]</font> SIM. <i>fr. 53 ;</i> ἄεισα <font color=\"brown\">[ᾰει-]</font> OD. <i>21, 411. Prés. éol</i>. ἀΐδω, COR.</p><p><b>Étym</b>. <i>p.-ê. indo-europ</i>. *h²ueid-, chanter.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αδω - ᾄδω</font>\n<br><br>mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Éphésiens (1) => <a class=\"ref\" data-r=\"EPH5.19\">Éphésiens 5.19</a></li>\n<li>Colossiens (1) => <a class=\"ref\" data-r=\"COL3.16\">Colossiens 3.16</a></li>\n<li>Apocalypse (3) => <a class=\"ref\" data-r=\"REV5.9;14.3;15.3\">Apocalypse 5.9 ; 14.3 ; 15.3</a></li>\n</ul>\n</td></tr>\n</table>","G104":"<h1>aei</h1>\n<p>Strong n° 104 <i>Prononciation [ah-eye']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>perpétuellement, sans cesse, toujours, constamment, depuis toujours</li>\n<li>invariablement, à toute heure</li>\n<li>quelque chose qui doit être refait selon les circonstances, toujours à nouveau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀεί</b> <i>adv. :</i><br><b> 1</b> toujours, HOM. (<i>v. ci-dessous) etc. ; pléon. avec d’autres adv. ou loc. marquant une idée de temps :</i> διαμπερὲς, συνεχὲς, ἐμμενὲς αἰεί (<i>poét</i>.) HOM. (<i>v. ces mots</i>) toujours, sans cesse, continuellement ; διὰ παντὸς ἀεὶ τοῦ χρόνου, XÉN. <i>Cyr. 8, 2, 1,</i> tout le temps, d’une manière continue ; ἀεί ποτε (<i>avec un prés</i>. HDT. <i>1, 58 ;</i> THC. <i>6, 82, etc. ; avec un impf</i>. HDT. <i>8, 29 ;</i> SOPH. <i>Aj. 320, etc. ; rar. avec un ao</i>. DC. <i>42, 1 et 5 ; 66, 10) ou</i> ἀεὶ δή ποτε, THC. <i>1, 13,</i> de tout temps ; <i>précédé d’une prép</i>. ἐς ἀεί, THC. <i>1, 22 et 23 ;</i> εἰς ἀεί, SOPH. <i>Aj. 343,</i> pour toujours ; ἐς τόδε ἀεί, THC. <i>1, 69,</i> jusqu’ici sans interruption ; <i>entre l’art. et un subst</i>. ὁ ἀεὶ χρόνος, HDT. <i>1, 54 ;</i> PLAT. <i>Phæd. 103</i> e, l’éternité ; οἱ ἀεὶ ὄντες, XÉN. <i>Cyr. 8, 7, 32,</i> les immortels ;<br><b> 2</b> chaque fois, <i>avec idée non de continuité, mais de répétition, pour exprimer un fait habituel, au sens de</i> ἑκάστοτε « chaque fois » : θῶπτε τὸν κρατοῦντ' ἀεί, ESCHL. <i>Pr. 937,</i> flatte chaque fois le maître du jour ; ὁ δ' ἀεὶ ξυντυχών, EUR. <i>Hec. 1182,</i> toutes les fois qu’un homme a affaire (à cette engeance, il connaît la vérité de ce que je dis) ; ἀεὶ ἀνὰ πᾶσαν ἡμέρην, HDT. <i>9, 38 ;</i> ἀεὶ παρ' ἑκάστην ἡμέραν, XÉN. <i>Hell. 1, 4, 15,</i> toujours chaque jour ; ἀεὶ ἑκάστοτε, AR. <i>Nub. 1478,</i> toujours chaque fois ; ἀεὶ καὶ μᾶλλον, POL. <i>1, 42, 10 ;</i> ἀεὶ μᾶλλον, DS. <i>4, 54, etc. ;</i> μᾶλλον ἀεί, PLUT. <i>Flam. 9,</i> chaque fois <i>ou</i> toujours plus, de plus en plus ; <i>particul. dans les prov</i>. <font color=\"blue\">ἀεὶ κακοὶ Φρύγες</font>, EUR. <i>Or. 1488,</i> les Phrygiens sont toujours (<i>càd</i>. tous) mauvais ; <i>cf</i>. EUR. <i>Or. 605 ;</i><br><b> 3</b> <i>p. suite,</i> successivement, tour à tour, au fur et à mesure : ὁ ἀεὶ βασιλεύων, THC. <i>9, 116 ;</i> ATH. <i>235</i> a, celui qui règne à son tour ; ἕτεροι δὲ παρέδοσαν τὸν ἀεὶ ἐξορυσσόμενον χοῦν ἄλλοισι, HDT. <i>7, 23,</i> les uns passaient aux autres la terre du terrassement au fur et à mesure qu’elle était retirée ; τὰς ἀεὶ πληρουμένας ἐξέπεμπον, THC. <i>3, 77,</i> ils faisaient partir les navires à mesure que les équipages étaient au complet ; <i>cf</i>. THC. <i>1, 11 ; 2, 37, etc</i>.<p><b>➼</b> <i>Dans Hom. d’ord</i>. αἰεί (<i>v. ci-dessus), 4 fois</i> ἀεί, IL. <i>12, 24 ; 23, 648 ;</i> OD. <i>15, 379 ;</i> BATR. <i>175. Dans Hom. et les Trag</i>. αἰέν <i>quand le mètre demande une finale brève,</i> IL. <i>1, 290, etc. ;</i> ESCHL. <i>Pr. 428, etc. ;</i> SOPH. <i>Aj. 682. Dans les inscr. att</i>. αἰεί <i>ou</i> ἀεί <i>j. en 361 av. J.C. ; à partir de 361 seul</i>. ἀεί, <i>excepté dans les décrets concernant les corporations religieuses où αἰεί se rencontre j. au 2<sup>e</sup> siècle av. J.C. (v. Meisterh. p. 25, 4 et p. 24, note 140). Dor</i>. αἰές, AR. <i>Lys. 1267 ; ou</i> ἀέ, PD. <i>P. 9, 91 dout. Éol</i>. ἀΐ, <i>ou mieux</i> ἄϊ, SAPPH.</p><p><b>Étym</b>. <i>cf</i>. αἰών.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αει - ἀεί</font>\n<br><br>vient d'un nom primaire, du sens apparent de durée continue</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 7 livres bibliques (NT)\n<ul>\n<li>Marc (1) => <a class=\"ref\" data-r=\"MRK15.8\">Marc 15.8</a></li>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT7.51\">Actes 7.51</a></li>\n<li>2 Corinthiens (2) => <a class=\"ref\" data-r=\"2CO4.11;6.10\">2 Corinthiens 4.11 ; 6.10</a></li>\n<li>Tite (1) => <a class=\"ref\" data-r=\"TIT1.12\">Tite 1.12</a></li>\n<li>Hébreux (1)=> <a class=\"ref\" data-r=\"HEB3.10\">Hébreux 3.10</a></li>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE3.15\">1 Pierre 3.15</a></li>\n<li>2 Pierre (1) => <a class=\"ref\" data-r=\"2PE1.12\">2 Pierre 1.12</a></li>\n</ul>\n</td></tr>\n</table>","G105":"<h1>aetos</h1>\n<p>Strong n° 105 Prononciation [ah-et-os']</p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un aigle : celui-ci ne se nourrissant généralement pas de charogne, il peut être question d'un volatile ressemblant à un aigle</li>\n<li>un aigle, en tant qu'étendard (Militaires Romains) un aigle symbole de l'être céleste, représente l'évangéliste Jean</li>\n<li>vautour, rapace</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀετός</b> <b>οῦ (ὁ)</b> <font color=\"brown\">[ᾱ]</font> :<br><b>   I</b> aigle, HOM. <i>(épq</i>. αἰετός, <i>v. ci-dessous), etc. ; prov</i>. <font color=\"blue\">ἀ. ἐν νεφέλαις</font>, AR. <i>Eq. 1010,</i> aigle dans les nuages, <i>càd</i>. chose inabordable ; <i>au sens de présage,</i> IL. <i>12, 243 ;</i> THCR. <i>Idyl. 26, 31 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b> 1</b> aigle, <i>enseigne militaire des Perses,</i> XÉN. <i>Cyr. 7, 1, 4 ; ou des Romains,</i> PLUT. <i>Mar. 23, etc. ;</i><br><b> 2</b> sorte de raie, <i>poisson,</i> ARSTT. <i>H.A. 5, 5, 3 ;</i><br><b> 3</b> fronton d’un édifice, faîte d’un temple (<i>cf</i>. ἀέτωμα) AR. <i>Av. 1110 ;</i> entablement au sommet d’une tour, ATHÉNÉE MÉC. <i>13, 5</i>.<p><b>➼</b> <i>Épq. et ion., qqf. trag</i>. αἰετός, IL. <i>8, 247, etc. ; seule forme dans les inscr. att</i>. CIA. <i>1, 322, a, 2, 80 (409 av. J.C.), etc. (v. Meisterh. p. 24, 1, note 142) ; mais v</i>. ἀέτωμα ; <i>dor</i>. αἰητός, PD. <i>P. 4, 6</i>.</p><p><b>Étym</b>. αἰετός <i>p</i>. *αἰϝετος, <i>de indo-europ</i>. *h²eu-i-, oiseau ; <i>cf. lat</i>. avis.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αετος - ἀετός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT24.28\">Matthieu 24.28</a></li>\n<li>Luc (1) => <a class=\"ref\" data-r=\"LUK17.37\">Luc 17.37</a></li>\n<li>Apocalypse (2) => <a class=\"ref\" data-r=\"REV4.7;12.14\">Apocalypse 4.7 ; 12.14</a></li>\n</ul>\n</td></tr>\n</table>","G106":"<h1>azumos</h1>\n<p>Strong n° 106 <i>Prononciation [ad'-zoo-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>non fermenté, exempt de levain ou levure\n<ol type=\"a\">\n<li>pain sans levain utilisé par les Juifs pour la Pâque</li>\n<li>métaph. libre de fautes, du « levain de l'iniquité »</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἄζυμος</b> <b>ἄ·ζυμος, ος, ον</b> <font color=\"brown\">[ῡ]</font> :<br><b> 1</b> sans levain, ATH. <i>109</i> b ; SPT. <i>Gen. 19, 3 ; Ex. 12, 39, etc. ;</i> τὰ ἄζ. pains sans levain, SPT. <i>Ex. 12, 15 et 18 ; Deut. 16, 4, 8 ;</i> JOS. <i>A.J. 3, 10, 5 ; d’où</i> fête des azymes, <i>càd</i>. des pains sans levain, SPT. <i>Ex. 23, 15 ; Lev. 23, 6, etc. ;</i> NT. <i>Matth. 26, 17 ; Marc. 14, 12 ; Luc. 22, 7 ;</i><br><b> 2</b> <i>p. suite,</i> compact, ferme, PLAT. <i>Tim. 74</i> d.<p><b>Étym</b>. ἀ, ζύμη.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-ζυμος - ἄζυμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT26.17\">Matthieu 26.17</a></li>\n<li>Marc (2) => <a class=\"ref\" data-r=\"MRK14.1,12\">Marc 14.1, 12</a></li>\n<li>Luc (2) => <a class=\"ref\" data-r=\"LUK22.1,7\">Luc 22.1, 7</a></li>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT12.3;20.6\">Actes 12.3 ; 20.6</a></li>\n<li>1 Corinthiens (2) => <a class=\"ref\" data-r=\"1CO5.7,8\">1 Corinthiens 5.7,8</a></li>\n</ul>\n</td></tr>\n</table>","G107":"<h1>Azor</h1>\n<p>Strong n° 107 <i>Prononciation [ad-zore']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Azor = « qui aide »\n<ol><li>un fils d'Eliakim, dans la généalogie du Seigneur (<a class=\"ref\" data-r=\"MAT1.13-14\">Mt 1.13, 14</a>)</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αζωρ</font> &lt; עזור - <font face=\"Georgia\">Ἀζώρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2) => <a class=\"ref\" data-r=\"MAT1.13,14\">Matthieu 1.13, 14</a></li>\n</ul>\n</td></tr>\n</table>","G108":"<h1>Azotos</h1>\n<p>Strong n° 108 <i>Prononciation [ad'-zo-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Azot (Angl. Ashdod ou Azotus) = « une forteresse », « un fort »\n<ol><li>une des cinq villes principales des Philistins, entre Askalon et Jamnia et proche de la Méditerranée</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></td></tr>\n<tr><td colspan=\"2\">\n <b>Ἀζωτός</b> <i>v</i>. Ἄζωτος.<b>Ἄζωτος</b> <b>ου</b>, <i>ou</i> <b>Ἀζωτός, οῦ (ἡ)</b> Azot (<i>auj</i>. Ashdod) <i>v. de Palestine,</i> HDT. <i>2, 157, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αζωτος</font> &lt; אשדוד - <font face=\"Georgia\">Ἄζωτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT8.40\">Actes 8.40</a></li>\n</ul>\n</td></tr>\n</table>","G109":"<h1>aer</h1>\n<p>Strong n° 109 <i>Prononciation [ah-ayr']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'air, bas et dense, différent de celui qui est haut et raréfié</li>\n<li>atmosphère</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀήρ</b> <b>ἀέρος</b> (ὁ, <i>poét</i>. ἡ) <font color=\"brown\">[ᾱ]</font> :<br><b>   I.1</b> <i>dans Hom. et Hés</i>. air ou atmosphère autour de la terre (<i>p. opp. à</i> αἰθήρ, région supérieure de l’air) IL. <i>14, 288 ;</i><br><b> 2</b> <i>p. suite,</i> vapeur, brume, brouillard, IL. <i>5, 776, etc. ; rapproché de</i> ὀμίχλη, IL. <i>17, 649 ;</i><br><b> 3</b> <i>p. ext</i>. le ciel, <i>en gén., p. opp. à</i> θάλασσα, <i>en parl. d’un décor de théâtre où l’on ne voit que le ciel et l’eau,</i> HÉRON <i>Aut. 265 ;</i><br><b> 4</b> <i>p. suite,</i> couleur du ciel, bleu de ciel, azur, <i>p. opp. à</i> μέλαν, <i>en part. d’un décor de théâtre badigeonné de noir ou d’azur,</i> HÉRON <i>Aut. 272 ;</i><br><b>   II</b> <i>postér. :</i><br><b> 1</b> air qu’on respire, <i>en gén</i>. SOPH. <i>El. 87 ;</i> AR. <i>Av. 694, etc. ;</i> πρὸς τὸν ἀέρα διατρίϐειν, AR. <i>Nub. 198,</i> demeurer (trop longtemps) en plein air ; <i>au pl</i>. PLAT. <i>Phæd. 98</i> c ;<br><b> 2</b> vapeurs <i>ou</i> exhalaisons méphitiques, STR. <i>284</i>.<p><b>➼</b> ἡ ἀ. HOM. <i>et</i> HÉS. (<i>excepté O. 547) ; cf. lat</i>. aer <i>égal. fém. dans</i> ENN. (A. GELL. <i>13, 21, 14). Par exc</i>. <font color=\"brown\">[ᾰ]</font> Ps.-PHOCYL. <i>108 ;</i> ARSTT. <i>fr. 642</i> (EUST. <i>Il. 17, 37). Épq. et ion</i>. ἀήρ, <i>gén</i>. ἠέρος, HOM. <i>ll. cc. ; mais</i> ἠήρ, HPC. <i>Aër. 282, 290</i>.</p><p><b>Étym</b>. <i>sign. primaire</i> « brume matinale » ; <i>R. indo-europ</i>. *h²eus-ēr-, aube ; <i>cf</i>. αὔρα, ἦρι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αηρ - ἀήρ</font>\n<br><br>vient de aemi (respirer inconsciemment)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT22.23\">Actes 22.23</a></li>\n<li>1 Corinthiens (2) => <a class=\"ref\" data-r=\"1CO9.26;14.9\">1 Corinthiens 9.26 ; 14.9</a></li>\n<li>Éphésiens (1) => <a class=\"ref\" data-r=\"EPH2.2\">Éphésiens 2.2</a></li>\n<li>1 Thessaloniciens (1) => <a class=\"ref\" data-r=\"1TH4.17\">1 Thessaloniciens 4.17</a></li>\n<li>Apocalypse (2) => <a class=\"ref\" data-r=\"REV9.2;16.17\">Apocalypse 9.2 ; 16.17</a></li>\n</ul>\n</td></tr>\n</table>","G110":"<h1>athanasia</h1>\n<p>Strong n° 110 <i>Prononciation [ath-an-as-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>impérissable, immortalité, éternel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀθανασία</b> <b>ας (ἡ)</b> <font color=\"brown\">[ᾱᾰᾰσ]</font> immortalité, PLAT. <i>Phædr. 246</i> a.<p><b>➼</b> <font color=\"brown\">[ῑ]</font> SIB. <i>2, 41, 150</i>.</p><p><b>Étym</b>. ἀθάνατος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αθανασια - ἀθανασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2) => <a class=\"ref\" data-r=\"1CO15.53,54\">1 Corinthiens 15.53, 54</a></li>\n<li>1 Timothée (1) => <a class=\"ref\" data-r=\"1TI6.16\">1 Timothée 6.16</a></li>\n</ul>\n</td></tr>\n</table>","G111":"<h1>athemitos</h1>\n<p>Strong n° 111 <i>Prononciation [ath-em'-ee-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans règle, débauché</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀθέμιτος</b> <b>ἀ·θέμιτος, ος, ον</b> <font color=\"brown\">[ῐ]</font> <i>c</i>. ἀθέμιστος, HDT. <i>7, 33 ;</i> ANT. <i>113, 39, etc</i>.<br><br><b>ἀ·θέμιστος, ος, ον</b> :<br>      1</b> <i>en parl. de pers</i>. sans loi, sans règle, criminel, IL. <i>9, 63 ;</i> OD. <i>9, 106 ;</i> XÉN. <i>Cyr. 8, 8, 5 ;</i><br><b>      2</b> <i>en parl. de choses,</i> illicite, HDT. <i>8, 143 ;</i> XÉN. <i>Mem. 1, 1, 9, etc</i>.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>Cyr. 8, 8, 5</i>.<br><span><b>Étym</b>. ἀ, θέμις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-θεμιτος - ἀθέμιτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1) => <a class=\"ref\" data-r=\"ACT10.28\">Actes 10.28</a></li>\n<li>1 Pierre (1) => <a class=\"ref\" data-r=\"1PE4.3\">1 Pierre 4.3</a></li>\n</ul>\n</td></tr>\n</table>","G112":"<h1>atheos</h1>\n<p>Strong n° 112 <i>Prononciation [ath'-eh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans Dieu, ne connaissant et n'adorant aucun Dieu</li>\n<li>niant les dieux, en particulier ceux reconnus par l'état</li>\n<li>athée, impie</li>\n<li>abandonné des dieux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἄθεος</b> <b>ἄ·θεος, ος, ον :<br> 1</b> qui ne croit pas aux dieux, <i>particul</i>. aux dieux reconnus, PLAT. <i>Ap. 26</i> c ; <i>d’où</i> impie, ESCHL. <i>Eum. 151 ;</i> SOPH. <i>Tr. 1036 ;</i><br><b> 2</b> abandonné des dieux, SOPH. <i>O.R. 661 ;</i><br><b> 3</b> ἄθ. ὀνόματα, ATH. <i>448</i> e, noms propres ne rappelant celui d’aucun dieu (Platon, Socrate, <i>etc.) p. opp. aux</i> ὀν. θεοφόρα (Dionysios, Hermonymos, <i>etc</i>.).<br><i>● Sup</i>. -ώτατος, XÉN. <i>An. 2, 5, 12 ;</i> PLAT. <i>Rsp. 589</i> e, <i>etc</i>.<p><b>Étym</b>. ἀ, θεός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-θεος - ἄθεος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Éphésiens (1) => <a class=\"ref\" data-r=\"EPH2.12\">Éphésiens 2.12</a></li>\n</ul>\n</td></tr>\n</table>","G113":"<h1>athesmos</h1>\n<p>Strong n° 113 <i>Prononciation [ath'-es-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui ne tient pas compte des contraintes de la loi et satisfait ses convoitises, sans règle, débauché</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἄθεσμος</b> <b>ἄ·θεσμος, ος, ον</b>, illicite, inique, criminel, PLUT. <i>Cæs. 10</i>.<p><b>Étym</b>. ἀ, θεσμός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-θεσμος - ἄθεσμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (2) => <a class=\"ref\" data-r=\"2PE2.7;3.17\">2 Pierre 2.7 ; 3.17</a></li>\n</ul>\n</td></tr>\n</table>","G114":"<h1>atheteo</h1>\n<p>Strong n° 114 <i>Prononciation [ath-et-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rejeter, ne tenir aucun compte de, laisser de côté,</li>\n<li>nier l'efficacité de toute chose, annuler, rendre nul, faire échouer</li>\n<li>rejeter, refuser, mépriser, ne pas reconnaître, repousser</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀθετέω</b> <b>ἀθετέω-ῶ</b> <font color=\"darkgreen\">(<i>ao</i>. ἠθέτησα ; <i>pass. ao</i>. ἠθετήθην, <i>pf</i>. ἠθέτημαι)</font> mettre de côté, <i>d’où :</i><br><b> 1</b> violer un traité, un serment, <i>etc</i>. POL. <i>8, 2, 5, etc. ;</i> ἀθετήματα ἀθετεῖν τινι, SPT. <i>3Reg. 8, 50,</i> se rendre coupable envers qqn en violant des promesses ; ἀθ. τὸν νόμον, SPT. <i>Esaï. 24, 17,</i> violer la loi ;<br><b> 2</b> agir avec perfidie : τινα, SPT. <i>Deut. 21, 14, etc. ;</i> εἴς τινα, SPT. <i>Jer. 3, 20 ;</i> ἔν τινι, SPT. <i>Ex. 21, 8,</i> envers qqn ;<br><b> 3</b> repousser : τινα, NT. <i>Marc. 6, 21,</i> une demande de qqn ; τινι, POL. <i>12, 14, 6</i> refuser son assentiment à qqe ch. ; <i>t. de gr</i>. rejeter comme mauvais (un mot, <i>etc</i>.) DH. <i>Din. 9 ;</i> DL. <i>7, 34, etc. ;</i><br><b> 4</b> <i>abs</i>. violer la loi, se révolter, SPT. <i>1Reg. 13, 3 ;</i> εἴς τινα, SPT. <i>3Reg. 12, 19 ;</i> ἔν τινι, SPT. <i>4Reg. 18, 7,</i> contre qqn.<p><b>Étym</b>. ἄθετος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αθετεω - ἀθετέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 12 versets de 9 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G115":"<h1>athetesis</h1>\n<p>Strong n° 115 <i>Prononciation [ath-et'-ay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>abolition, annulation, rejet, abrogation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀθέτησις</b> <b>εως (ἡ) :<br> 1</b> abolition, rejet, <i>en gén</i>. NT. <i>Hebr. 7, 18 ; 9, 26 ;</i><br><b> 2</b> <i>t. de gr</i>. rejet d’une leçon vicieuse, DL. <i>3, 66 ;</i> DYSC. <i>Synt. 5, 8 ; 163, 5</i>.<p><b>Étym</b>. ἀθετέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-θετησις - ἀθέτησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2) => <a class=\"ref\" data-r=\"HEB7.18;9.26\">Hébreux 7.18 ; 9.26</a></li>\n</ul>\n</td></tr>\n</table>","G116":"<h1>Athenai</h1>\n<p>Strong n° 116 <i>Prononciation [ath-ay-nahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Athènes (Angl. Athens) = « incertitude », « sans augmentation »\n<ol><li>fameuse cité Grecque, capitale de l'Attique, et siège principal de l'enseignement et de la civilisation pendant l'époque d'or de l'histoire de la Grèce</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>Ἀθῆναι</b> <b>ῶν (αἱ) :<br> 1</b> Athènes, <i>n. de v</i>. OD. <i>3, 307, etc. ;</i><br><b> 2</b> l’Attique, OD. <i>3, 278 ;</i> HDT. <i>9, 17 ;</i> THC. <i>2, 93 ;</i> XÉN. <i>Hell. 7, 1, 23, etc. ;</i> ἄκρον Ἀθηνέων, OD. <i>3, 278,</i> le promontoire d’Attique, <i>càd</i>. Sounion (Sunium).<p><b>➼</b> <i>Dor</i>. Ἀθᾶναι, PD. <i>P. 7, 1 ;</i> ESCHL. <i>Pers. 975 ;</i> SOPH. <i>Aj. 1222 ; gén</i>. Ἀθανᾶν, PD. <i>N. 4, 30 ; gén. épq</i>. Ἀθηνάων, OD. <i>3, 307 ; gén. ion</i>. Ἀθηνέων, OD. <i>3, 278 ;</i> HDT. <i>1, 98, etc</i>.</p><p><b>Étym</b>. <i>pré-grec</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αθηναι - Ἀθῆναι</font>\n<br><br>pluriel d'Athéna (la déesse de la sagesse, considérée comme fondatrice de la ville)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (3) => <a class=\"ref\" data-r=\"ACT17.15,16;18.1\">Actes 17.15, 16 ; 18.1</a></li>\n<li>1 Thessaloniciens (1) => <a class=\"ref\" data-r=\"1TH3.1\">1 Thessaloniciens 3.1</a></li>\n</ul>\n</td></tr>\n</table>","G117":"<h1>Athenaios</h1>\n<p>Strong n° 117 <i>Prononciation [ath-ay-nah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une personne qui vit à Athènes, un Athénien, une Athénienne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>Ἀθηναῖος</b> <b>α, ον</b> <font color=\"brown\">[ᾰ]</font> Athénien, IL. <i>2, 551 ;</i> XÉN. <i>Hell. 2, 2, 1, etc. ;</i> οἱ Ἀθ. ATT. <i>etc</i>. Athéniens.<p><b>➼</b> <i>Fém. rare ; on emploie de préfér</i>. Ἀττική <i>ou</i> Ἀτθίς. <i>Dor</i>. Ἀθαναῖος <font color=\"brown\">[ᾰᾱ]</font> PD. <i>P. 1, 148, etc. ; lac. acc. pl</i>. Ἀσαναίως <font color=\"brown\">[ᾱν]</font> AR. <i>Lys. 170, 1244, 1250</i>.</p><p><b>Étym</b>. Ἀθῆναι.<b>Ἀθήναιος</b> <b>ου (ὁ)</b> Athènæos, <i>h</i>. THC. <i>4, 119, 122, etc</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αθηναιος - Ἀθηναῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT17.21,22\">Actes 17.21, 22</a></li>\n</ul>\n</td></tr>\n</table>","G118":"<h1>athleo</h1>\n<p>Strong n° 118 <i>Prononciation [ath-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>engagé dans une lutte, lutter dans des jeux sportifs, lutter pour un prix</li>\n<li>supporter, endurer, souffrir</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀθλέω</b> <b>ἀθλέω-ῶ</b> <font color=\"darkgreen\">(<i>f</i>. ήσω, <i>ao</i>. ἤθλησα, <i>pf</i>. ἤθληκα)</font><br><b>   I</b> lutter, <i>d’où :</i><br><b> 1</b> lutter : πρός τινα, HDT. <i>1, 67,</i> contre qqn ; ἀθλ. ἄθλους, PLAT. <i>Tim. 19</i> c, soutenir des luttes ; <i>en parl. d’une bataille,</i> combattre, HDT. <i>7, 212 ; au sens mor</i>. ἀθλ. πόνον, EUR. <i>Suppl. 317,</i> subir une épreuve pénible ; ἀθλ. κινδυνεύματα, SOPH. <i>O.C. 564,</i> avoir à lutter contre des dangers ;<br><b> 2</b> être athlète, PLUT. ;<br><b>   II</b> faire avec effort : (πόλιν) Λαομέδοντι, IL. <i>7, 453,</i> construire à force de travail (une ville) pour Laomédon.<p><b>➼</b> <i>Ion</i>. ἀεθλέω : <i>impf sans augm. 3 sg</i>. ἀέθλεε, ANTH. <i>App. 5 ; 3 pl</i>. ἀέθλεον, HDT. <i>1, 67, etc</i>.</p><p><b>Étym</b>. ἄθλον.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αθλεω - ἀθλέω</font>\n<br><br>vient de athlos (concours dans les listes publiques)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (2) => <a class=\"ref\" data-r=\"2TI2.5\">2 Timothée 2.5</a></li>\n</ul>\n</td></tr>\n</table>","G119":"<h1>athlesis</h1>\n<p>Strong n° 119 <i>Prononciation [ath'-lay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lutter, combattre, s'efforcer, dure épreuve, combat (athlétique)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἄθλησις</b> <b>εως (ἡ)</b> <font color=\"brown\">[ᾱ]</font> :<br><b> 1</b> lutte <i>ou</i> exercice d’athlète, POL. <i>5, 64, 6 ; 7, 10, 2 ;</i> PLUT. <i>Thes. 19, etc. ;</i><br><b> 2</b> épreuve pénible, NT. <i>Hebr. 10, 32</i>.<p><b>Étym</b>. ἀθλέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αθλησις - ἄθλησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB10.32\">Hébreux 10.32</a></li>\n</ul>\n</td></tr>\n</table>","G120":"<h1>athumeo</h1>\n<p>Strong n° 120 <i>Prononciation [ath-oo-meh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être découragé, brisé en esprit, perdre courage, être abattu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀθυμέω</b> <b>ἀθυμέω-ῶ</b> <font color=\"brown\">[ῡ]</font> être découragé, préoccupé, inquiet : τινι, SOPH. <i>El. 769 ;</i> ἐπί τινι, ISOCR. <i>41</i> b ; τι, THC. <i>5, 91 ;</i> εἴς τι, PLAT. <i>Soph. 264</i> b ; πρός τι, THC. <i>2, 88,</i> de qqe ch., par suite de qqe ch. ; <i>avec une conj</i>. ἀθ. εἰ, SOPH. <i>Tr. 666,</i> craindre <i>de, etc. ;</i> ἐκεῖνο ἀθυμῶ ὅτι, XÉN. <i>Mem. 4, 3, 15,</i> je crains que ; ἀθυμεῖν μή, SOPH. <i>O.R. 747,</i> craindre que ; <i>avec un part</i>. craindre que, DS. <i>11, 13 et 25 ;</i> PLUT. <i>M. 80</i> c ; <i>avec l’inf</i>. THC. <i>7, 21</i>.<p><b>Étym</b>. ἄθυμος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αθυμεω - ἀθυμέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1) => <a class=\"ref\" data-r=\"COL3.21\">Colossiens 3.21</a></li>\n</ul>\n</td></tr>\n</table>","G121":"<h1>athoos</h1>\n<p>Strong n° 121 <i>Prononciation [ath'-o-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non coupable, innocent, impuni, non concerné</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>ἀθῷος</b> <b>ἀ·θῷος, ος, ον :<br>   I</b> <i>pass. :</i><br><b> 1</b> impuni, qui ne reçoit pas le châtiment de, <i>gén</i>. LYCURG. <i>157, 38 ;</i> DS. <i>14, 76, etc. ; abs</i>. PLAT. <i>Soph. 254</i> e ; DÉM. <i>549, 27, etc. ; p. ext</i>. qui n’a pas à souffrir de, non atteint par, <i>gén</i>. AR. <i>Nub. 1413 ;</i> DÉM. <i>316, 18 ;</i><br><b> 2</b> qui ne mérite pas d’être puni, innocent : ἀπό τινος, SPT. <i>2Reg. 3, 28 ;</i> NT. <i>Matth. 27, 4 et 24,</i> de qqe chose ; <i>abs</i>. DÉM. <i>269, 4 ;</i> SPT. <i>Num. 32, 22 ; Deut. 27, 25, etc. ;</i><br><b>   II</b> <i>act</i>. qui ne cause aucun dommage, DÉM. <i>1437, 9</i>.<p><b>Étym</b>. ἀ, θωή.<b>Ἀθῶος</b> <b>η, ον</b>, de l’Athos, ESCHL. <i>Ag. 285 ;</i> SOPH. <i>fr. 229 Dind</i>. (-ῷος).</p><p><b>Étym</b>. Ἄθως.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αθωος - ἀθῷος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2) => <a class=\"ref\" data-r=\"MAT27.4,24\">Matthieu 27.4, 24</a></li>\n</ul>\n</td></tr>\n</table>","G122":"<h1>aigeos</h1>\n<p>Strong n° 122 <i>Prononciation [ah'-ee-ghi-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>peau de chèvre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>Αἰγεῖος</b> <b>α, ον</b>, d’Égée : τὸ Αἰγεῖον, DIN. (<i>Bkk. 354</i>) temple d’Égée.<p><b>Étym</b>. Αἰγεύς.<b>αἴγειος</b> <b>α, ον</b>, de chèvre, IL. <i>3, 247, etc. ;</i> ARSTT. <i>H.A. 3, 20, 12</i>.</p><p><b>➼</b> <i>Fém. ion</i>. -είη, OD. <i>24, 231</i>.</p><p><b>Étym</b>. αἴξ ; <i>cf</i>. αἴγεος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιγεος - αἴγειος</font>\n<br><br>vient de aix (une chèvre)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB11.37\">Hébreux 11.37</a></li>\n</ul>\n</td></tr>\n</table>","G123":"<h1>aigialos</h1>\n<p>Strong n° 123 <i>Prononciation [ahee-ghee-al-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le rivage de la mer, la plage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>Αἰγιαλός</b> <b>οῦ (ὁ)</b> <font color=\"brown\">[ᾰ]</font> Ægialos :<br><b> 1</b> <i>anc. n. de l’Achaïe, puis du Péloponnèse,</i> IL. <i>2, 575 ;</i><br><b> 2</b> <i>côte et lieu de Paphlagonie,</i> IL. <i>2, 855 ; pl</i>. Αἰγιαλοί, LUC. <i>Alex. 57 m. sign</i>.<p><b>Étym</b>. αἰγιαλός.<b>αἰγιαλός</b> <b>οῦ (ὁ)</b> <font color=\"brown\">[ᾰ]</font> bord de la mer, rivage, grève, IL. <i>4, 422 ;</i> OD. <i>22, 385 ;</i> THC. <i>1, 7 ;</i> XÉN. <i>An. 6, 4, 4 ; distingué de</i> ἀκτή, ARSTT. <i>H.A. 5, 15, 6</i>.</p><p><b>Étym</b>. αἶγες, vagues, <i>v</i>. αἴξ II, 4, <i>et</i> ἅλς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιγιολος - αἰγιαλός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2) => <a class=\"ref\" data-r=\"MAT13.2,48\">Matthieu 13.2, 48</a></li>\n<li>Jean (1) => <a class=\"ref\" data-r=\"JHN21.4\">Jean 21.4</a></li>\n<li>Actes (3) => <a class=\"ref\" data-r=\"ACT21.5;27.39,40\">Actes 21.5 ; 27.39, 40</a></li>\n</ul>\n</td></tr>\n</table>","G124":"<h1>Aiguptios</h1>\n<p>Strong n° 124 <i>Prononciation [ahee-goop'-tee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un Egyptien, habitant de l'Egypte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n <b>Αἰγύπτιος</b> <b>α, ον</b>, d’Ægyptos, ESCHL. <i>Suppl. 817, ou</i> d’Égypte, HOM. <i>etc. ;</i> τὸ Αἰγ. DC. <i>42, 35,</i> le royaume d’Égypte ; τὰ Αἰγ. APP. <i>Mithr. 114,</i> l’histoire d’Égypte.<p><b>➼</b> <i>Dat. pl. f. épq</i>. -ίῃσι, OD. <i>4, 127. Les formes où</i> ι <i>est suivi d’une finale longue sont trisyll. en poésie,</i> OD. <i>4, 83, 127, 229 ; 17, 432 ;</i> NONN. <i>D. 3, 282, etc</i>.</p><p><b>Étym</b>. Αἴγυπτος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αιγυπτιος - Αἰγύπτιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (4) => <a class=\"ref\" data-r=\"ACT7.22,24,28;21.38\">Actes 7.22, 24, 28 ; 21.38</a></li>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB11.29\">Hébreux 11.29</a></li>\n</ul>\n</td></tr>\n</table>","G125":"<h1>Aiguptos</h1>\n<p>Strong n° 125 <i>Prononciation [ah'-ee-goop-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Egypte (Angl. Egypt) = « double détroit, oppresseur »\n<ol>\n<li>contrée à l'angle nord-est de l'Afrique</li>\n<li>métaph. Jérusalem, pour les Juifs persécutant Christ et ses disciples, et donc comme les Egyptiens traitant les Juifs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Αἴγυπτος</b> <b>ου :<br>   I (ὁ)</b> Ægyptos :<br><b> 1</b> <i>fils d’Hèphæstos,</i> Ps.-PLUT. <i>Fluv. 16 ; ou de Bèlos,</i> HDT. <i>1, 182 ;</i> ESCHL. <i>Suppl. 10, etc. ;</i><br><b> 2</b> <i>anc. n. du Nil,</i> OD. <i>4, 477, etc. ;</i><br><b>   II (ἡ)</b> Égypte, <i>contrée d’Afrique,</i> OD. <i>17, 448, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αιγυπτος - Αἴγυπτος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 22 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Actes (14)</li>\n<li>Hébreux (4)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G126":"<h1>aidios</h1>\n<p>Strong n° 126 <i>Prononciation [ah-id'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>éternel, éternellement, destiné à durer toujours.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀΐδιος</b> <b>ος, ον</b> <font color=\"brown\">[ᾱῐδ]</font> pour toujours, <i>d’où :</i><br><b> 1</b> éternel, <i>p. opp. à</i> γενητός, ARSTT. <i>Metaph. 8, 8, 15, et à</i> φθαρτός, ARSTT. <i>Nic. 6, 3, 2 ;</i> HH. <i>29, 3 ;</i> HÉS. <i>Sc. 310 ;</i> THC. <i>4, 20 ;</i> XÉN. <i>Ages. 11, 16 ;</i> ἡ ἀ. οὐσία, PLAT. <i>Tim. 37</i> e, existence éternelle, éternité : ἐς ἀΐδιον, THC. <i>4, 63,</i> pour toujours ;<br><b> 2</b> perpétuel : ἀ. στρατηγία, ἀρχή, <i>etc</i>. ARSTT. <i>Pol. 3, 14, 4, etc</i>. commandement perpétuel, <i>etc. ; en parl. de pers</i>. ἀ. βασιλεῖς, ARSTT. <i>Pol. 3, 13, 25,</i> rois perpétuels <i>ou</i> à vie.<br><i>● Cp</i>. -ώτερος, ARSTT. <i>Cæl. 2, 1</i>.<p><b>➼</b> <i>Fém</i>. -ίη, ORPH. <i>H. 9, 21</i>.</p><p><b>Étym</b>. ἀεί.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιδιος - ἀΐδιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> - couvre l'idée philosophique complète - sans commencement ET sans fin ; également soit sans commencement OU sans fin ; par rapport au passé, ce mot est appliqué à ce qui a existé à une période trop loin pour l'esprit\n<br><br> - donne la prééminence à l'éternité incommensurable</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1) => <a class=\"ref\" data-r=\"ROM1.20\">Romains 1.20</a></li>\n<li>Jude (1) => <a class=\"ref\" data-r=\"JUD1.6\">Jude 6</a></li>\n</ul>\n</td></tr>\n</table>","G127":"<h1>aidos</h1>\n<p>Strong n° 127 <i>Prononciation [ahee-doce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sens de honte, d'honneur, de modestie, timidité, révérence, décence, pudeur, égard pour les autres, respect</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰδώς</b> <b>όος-οῦς (ἡ) :<br>   I</b> <i>pass. :</i><br><b> 1</b> sentiment de l’honneur, IL. <i>15, 561, etc. ; d’ord. différ. de</i> αἰσχύνη (honte qu’on éprouve d’une mauvaise action) ; <i>ttef. synon. de</i> αἰσχύνη, <i>au sens de</i> « sentiment de l’honneur », THC. <i>1, 84 ; joint à</i> δέος, IL. <i>15, 657 ;</i><br><b> 2</b> honte, pudeur : αἰδώς τίς μ' ἔχει, PLAT. <i>Soph. 217</i> d, une sorte de honte me retient ; αἰδοῦς ἐμπίπλασθαι, XÉN. <i>Cyr. 1, 4, 4,</i> être plein de modestie ; <i>particul. en parl. de l’expression du regard :</i> δι' αἰδοῦς ἔχουσα ὄμμα ἐλεύθερον, EUR. <i>I.A. 994,</i> la pudeur voilant son noble regard ; <i>en ce sens différ. de</i> σωφροσύνη, <i>qui s’applique à l’ensemble de la tenue,</i> XÉN. <i>Mem. 2, 1, 22 ; cf. Cyr. 8, 1, 11 ; joint à</i> σωφροσύνη, XÉN. <i>Conv. 1, 8 ; avec l’inf</i>. honte <i>ou</i> crainte de, <i>etc</i>. ESCHL. <i>Ag. 922 ;</i><br><b> 3</b> honte, <i>c</i>. αἰσχύνη, THC. <i>1, 84 ;</i> τάχ' ἄν τιν' αἰδῶ κἀπ' ἐμοὶ βλέψας λάϐοι, SOPH. <i>Aj. 338,</i> peut-être éprouverait-il qqe honte (de son abattement), ne fût-ce qu’après avoir jeté les yeux sur moi ;<br><b> 4</b> crainte respectueuse, respect, THGN. <i>1266 ;</i> αἰδοῦς τυγχάνειν ὑπό τινος, XÉN. <i>Cyr. 1, 6, 10,</i> obtenir le respect de qqn ;<br><b> 5</b> <i>p. suite,</i> égards, pitié, miséricorde, respect de l’infortuné, SOPH. <i>O.C. 1268 ;</i> ANT. <i>114, 16 ;</i> PLAT. <i>Leg. 867</i> e ;<br><b>   II</b> <i>act. :</i><br><b> 1</b> ce qui cause la honte, sujet de honte : αἰδώς, Ἀργεῖοι, IL. <i>5, 787,</i> quelle honte ! Grecs ;<br><b> 2</b> ce qui cause le respect, dignité, majesté, HÉS. <i>O. 214 ;</i><br><b> 3</b> parties honteuses, IL. <i>2, 262 ;</i> DH. <i>1, 80</i>.<p><b>Étym</b>. αἴδομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιδως - αἰδώς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1) => <a class=\"ref\" data-r=\"1TI2.9\">1 Timothée 2.9</a></li>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB12.28\">Hébreux 12.28</a></li>\n</ul>\n</td></tr>\n</table>","G128":"<h1>Aithiops</h1>\n<p>Strong n° 128 <i>Prononciation [ahee-thee'-ops]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ethiopien (Angl. Ethiopian) = « noir, brûlé par le soleil »\n<ol><li>un Ethiopien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Αἰθίοψ</b> <b>Αἰθί·οψ, οπος (ὁ, ἡ) :<br>   I</b> <i>adj</i>. d’Éthiopie, éthiopien, <i>litt</i>. « au visage brûlé, noir » PD. <i>O. 2, 148 ;</i> ESCHL. <i>fr. 304, etc. ;</i><br><b>   II</b> <i>subst. :</i><br><b> 1</b> ὁ Αἰθ. l’Éthiopien, <i>surn. de Zeus,</i> LYC. <i>537 ;</i> ποταμὸς Αἰθίοψ, ESCHL. <i>Pr. 809,</i> le fleuve éthiopien, <i>càd</i>. le cours supérieur du Nil ;<br><b> 2</b> οἱ Αἰθίοπες, les Éthiopiens, IL. <i>23, 206 ;</i> HDT. <i>2, 22, etc</i>.<p><b>➼</b> <i>Dat. pl. poét</i>. -όπεσσι, PD. <i>N. 3, 103 ;</i> THCR. <i>Idyl. 7, 113, etc</i>.</p><p><b>Étym</b>. <i>pré-grec</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αιθιοψ - Αἰθίοψ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT8.27\">Actes 8.27</a></li>\n</ul>\n</td></tr>\n</table>","G129":"<h1>haima</h1>\n<p>Strong n° 129 <i>Prononciation [hah'-ee-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>expression σαρξ και αιμα = l'homme naturel ou la chair et le sang</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἷμα</b> <b>ατος (τὸ) :<br>A</b> sang, liquide sanguin :<br><b>   I</b> <i>au propre :</i><br><b> 1</b> <i>en gén</i>. IL. <i>1, 303, etc. ;</i> OD. <i>18, 97, etc. ;</i> ἐέρσας αἵματι μυδαλέας, IL. <i>11, 54,</i> des rosées mouillées de sang ; <i>en poésie avec l’épith. de</i> « noir » : μέλαν αἷμα, IL. <i>10, 297 ;</i> THCR. <i>Idyl. 2, 13 ;</i> αἷμα κελαινόν, IL. <i>1, 303,</i> sang noir ; <i>au pl</i>. flots de sang, ESCHL. <i>Ag. 1293 ;</i> SOPH. <i>Ant. 120 ;</i> EUR. <i>Alc. 496, etc. ;</i><br><b> 2</b> sang versé, meurtre, ESCHL. <i>Ch. 520, etc. ;</i> SOPH. <i>O.R. 101, etc. ;</i> EUR. <i>Or. 285, 406 ;</i> αἷμα κτανεῖν, SOPH. <i>fr. 153,</i> accomplir un meurtre ; ἀπόφονον αἷμα (<i>cf</i>. ἀπόφονον φόνον) EUR. <i>Or. 192,</i> sang qui n’aurait pas dû être répandu ; αἷμα γενέθλιον, EUR. <i>Or. 89,</i> meurtre (<i>litt</i>. sang répandu) d’une mère ; αἵματος δίκαι, ESCHL. <i>Eum. 682, ou</i> αἱμάτων δ. PLAT. <i>Leg. 872</i> b, accusation de meurtre ; ἐφ' αἵματι φεύγειν, DÉM. <i>548 fin ;</i> αἷμα φεύγειν, EUR. <i>Suppl. 148,</i> être banni comme coupable de meurtre ; αἷμα πράττειν, EUR. <i>Or. 1139,</i> faire payer la dette du sang ; αἵματος πράκτορες, ESCHL. <i>Eum. 319,</i> vengeresses qui exigent la rançon du sang ;<br><b> 3</b> menstrues, SPT. <i>Lev. 15, 19 ;</i><br><b>   II</b> <i>fig. :</i><br><b> 1</b> sang, liens du sang, parenté, race, <i>joint à</i> γένος, OD. <i>8, 583 ;</i> αἵματος εἶς ἀγαθοῖο, OD. <i>4, 611,</i> tu es d’un bon sang, d’une bonne race ; ἐξ αἵματος εἶναι, IL. <i>19, 111 ;</i> ἀφ' αἵματος εἶναι, SOPH. <i>O.C. 245 ;</i> ἐν αἵματι, ESCHL. <i>Eum. 606,</i> être du sang de qqn ; ὁ πρὸς αἵματος, SOPH. <i>Aj. 1305,</i> qui est du même sang, parent ; Περσήϊον αἷμα, THCR. <i>Idyl. 24, 72,</i> fils de Persée ;<br><b> 2</b> âme, ARSTT. <i>An. 1, 2, 21 ; d’où</i> force, courage, ESCHN. <i>76, 28 ;</i><br><b>B</b> <i>p. anal</i>. liquide rouge, <i>particul. :</i><br><b> 1</b> jus de raisin, vin, SPT. <i>Gen. 49, 11 ; Deut. 32, 14 ; Sir. 39, 26 ;</i> ANTH. <i>App. 69 ;</i> A. TAT. <i>2, 2 ; particul</i>. le vin (qui représente le sang de J.C.) NT. <i>Matth. 26, 28 ; Marc. 14, 24 ; Luc. 22, 20, etc. ;</i><br><b> 2</b> jus de mûres, SPT. <i>1Macc. 6, 34 ;</i><br><b> 3</b> pourpre des coquillages, LUC. <i>Cat. 16</i>.<p><b>Étym</b>. <i>Origine inconnue</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιμα - αἷμα</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n98 fois dans 91 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (3)</li>\n<li>Luc (8)</li>\n<li>Jean (6)</li>\n<li>Actes (12)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (4)</li>\n<li>Galates (1)</li>\n<li>Éphésiens (3)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (21)</li>\n<li>1 Pierre (2)</li>\n<li>1 Jean (4)</li>\n<li>Apocalypse (19)</li>\n</ul>\n</td></tr>\n</table>","G130":"<h1>haimatekchusia</h1>\n<p>Strong n° 130 <i>Prononciation [hahee-mat-ek-khoo-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>effusion de sang, action de faire couler du sang</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἱματεκχυσία</b> <b>αἱματ·εκχυσία, ας (ἡ)</b> <font color=\"brown\">[ῠ]</font> effusion de sang, NT. <i>Hebr. 9, 22</i>.<p><b>Étym</b>. αἷμα, ἐκχέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιματ-εκχυσια - αἱματεκχυσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB9.22\">Hébreux 9.22</a></li>\n</ul>\n</td></tr>\n</table>","G131":"<h1>haimorrheo</h1>\n<p>Strong n° 131 <i>Prononciation [hahee-mor-hreh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souffrir d'une perte de sang, perdre son sang, hémorragie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἱμορροέω</b> <b>αἱμορροέω-οῶ</b>, avoir un flux de sang, une hémorrhagie, HPC. <i>129</i> h, <i>etc. ;</i> NT. <i>Matth. 9, 20</i>.<p><b>Étym</b>. αἱμόρροος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιμορρεω - αἱμορροέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1) => <a class=\"ref\" data-r=\"MAT9.20\">Matthieu 9.20</a></li>\n</ul>\n</td></tr>\n</table>","G132":"<h1>Aineas</h1>\n<p>Strong n° 132 <i>Prononciation [ahee-neh'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Enée (Angl. Aeneas) = « louable »\n<ol><li>le nom d'un paralytique guéri par Pierre à Lydde</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Αἰνέας</b> <i>v</i>. Αἰνείας.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αινεας - Αἰνέας</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2) => <a class=\"ref\" data-r=\"ACT9.33,34\">Actes 9.33, 34</a></li>\n</ul>\n</td></tr>\n</table>","G133":"<h1>ainesis</h1>\n<p>Strong n° 133 <i>Prononciation [ah'-ee-nes-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>louange, offrande d'action de grâces, chanter la louange</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἴνεσις</b> <b>εως (ἡ)</b> louange, SPT. <i>Lev. 7, 2 ; 1Par. 16, 35 ; 2Esdr. 10, 11</i>.<p><b>Étym</b>. αἰνέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αινεσις - αἴνεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1) => <a class=\"ref\" data-r=\"HEB13.15\">Hébreux 13.15</a></li>\n</ul>\n</td></tr>\n</table>","G134":"<h1>aineo</h1>\n<p>Strong n° 134 <i>Prononciation [ahee-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>louer, chanter des louanges en l'honneur de Dieu</li>\n<li>permettre, recommander</li>\n<li>promettre, vœu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰνέω</b> <b>αἰνέω-ῶ</b> <font color=\"darkgreen\">(<i>impf</i>. ᾔνουν, <i>f</i>. αἰνέσω, <i>ao</i>. ᾔνεσα, <i>pf. inus. ; pass. ao</i>. ᾐνέθην, <i>pf. inus</i>.)</font><br><b>   I</b> parler de (<i>cf</i>. αἶνος) ; αἰν. τι, ESCHL. <i>Ag. 98 ;</i> SOPH. <i>Ph. 1380,</i> parler de qqe ch. ;<br><b>   II</b> trouver bon, <i>d’où :</i><br><b> 1</b> louer, approuver (<i>en ce sens, att</i>. ἐπαινέω) <i>abs</i>. IL. <i>8, 9 ;</i> EUR. <i>I.T. 1486 ; p. opp. à</i> ψέγειν, ESCHL. <i>Ag. 1403 ; avec l’acc</i>. τινα, IL. <i>23, 552 ;</i> τι, OD. <i>16, 380 ; p. opp. à</i> νεικέω, IL. <i>10, 249, ou à</i> μέμφομαι, SOPH. <i>Ant. 1157 ;</i> αἰν. τινά τινος, EUR. <i>I.A. 1371,</i> louer qqn de qqe ch. ; ἐπί τινι αἰνεῖσθαι, THCR. <i>Idyl. 16, 15,</i> être loué de qqe ch. ;<br><b> 2</b> acquiescer, consentir à : τι, ESCHL. <i>Eum. 469, etc. ;</i> EUR. <i>Alc. 2,</i> à qqe ch. ; <i>avec un part</i>. ἰόντ' αἰνέσατ' ἐκ δόμων, ESCHL. <i>Pers. 642,</i> laissez-le s’éloigner de votre demeure ;<br><b> 3</b> se résigner, EUR. <i>El. 1241 ;</i><br><b> 4</b> louer de, remercier de (<i>t. de refus poli) acc</i>. HÉS. <i>O. 641 ;</i> SOPH. <i>fr. 96 ;</i><br><b> 5</b> recommander, <i>euphém. p</i>. ordonner, prescrire, ESCHL. <i>Ch. 715 ;</i><br><b> 6</b> promettre : τινί τι, SOPH. <i>Ph. 1398,</i> qqe ch. à qqn ; τινι <i>avec une prop. inf</i>. EUR. <i>Alc. 12,</i> à qqn que, <i>etc</i>.<p><b>➼</b> <i>Fut. épq. et poét., non att.,</i> αἰνήσω, OD. <i>16, 380 ;</i> PD. <i>N. 1, 72, etc. Ao. poét</i>. ᾔνησα, IL. <i>23, 552, etc. ;</i> αἴνησα, PD. <i>P. 3, 13, etc. ; part. dor</i>. αἰνήσαις, PD. <i>O. 9, 14. Verbe poét. et de prose ion. ; en prose att. seul</i>. PLAT. <i>Rsp. 404</i> d, <i>Leg. 952</i> c.</p><p><b>Étym</b>. αἶνος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αινεω - αἰνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (4)</li>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G135":"<h1>ainigma</h1>\n<p>Strong n° 135 <i>Prononciation [ah'-ee-nig-ma]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une parole obscure, énigme</li>\n<li>une chose obscure</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἴνιγμα</b> <b>ατος (τὸ)</b> ce qu’on laisse entendre, <i>p. opp. à ce qu’on dit clairement, d’où :</i><br><b> 1</b> parole obscure <i>ou</i> équivoque, énigme, ESCHL. <i>Pr. 610 ;</i> SOPH. <i>O.R. 393, etc. ;</i> PLAT. <i>Ap. 27</i> a, <i>etc. ;</i> PLUT. <i>M. 671</i> e, <i>etc. ;</i> δι' αἰνιγμάτων, ESCHN. <i>70, 34,</i> par énigmes, en termes obscurs ;<br><b> 2</b> <i>p. ext. et sans idée d’obscurité ou d’équivoque,</i> ce qu’on laisse entendre par voie d’allusion <i>ou</i> d’apologue : Αἰσώπειον αἴνιγμα, SEXT. <i>310, 9 Bkk</i>. fable d’Ésope.<p><b>Étym</b>. αἰνίσσομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αινιγμα - αἴνιγμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G136":"<h1>ainos</h1>\n<p>Strong n° 136 <i>Prononciation [ah'-ee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un dire, un dicton, proverbe</li>\n<li>louange, discours élogieux, louange en public</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Αἶνος</b> <b>ου</b>, Ænos :<br><b> 1 (ἡ)</b> <i>v. de Thrace (auj</i>. Enez) HDT. <i>4, 90 ;</i> THC. <i>4, 28, etc. ;</i><br><b> 2 (ὁ)</b> <i>h</i>. Q. SM. <i>11, 79</i>.<b>αἰνός</b> <b>ή, όν</b>, terrible, affreux, effrayant, <i>en parl. de pers</i>. IL. <i>18, 361 ;</i> OD. <i>11, 427, et de choses (combat, dévastation, colère, etc</i>.) IL. <i>4, 15 ; 7, 40, etc. ;</i> OD. <i>15, 342 ;</i> PD. <i>P. 5, 61, etc. ;</i> SOPH. <i>Aj. 706 ; adv</i>. αἰνά, IL. <i>1, 414, etc. ;</i> OD. <i>22, 447, etc</i>.<br><i>● Cp</i>. -ότερος, DD. <i>11, 427 ;</i> <i>● Sup</i>. -ότατος, IL. <i>1, 552, neutre adv</i>. -ότατον, IL. <i>13, 52</i>.<p><b>Étym</b>. <i>cf</i>. αἴνυμαι.<b>αἶνος</b> <b>ου (ὁ) :<br> 1</b> récit, conte, histoire, OD. <i>14, 508 ;</i> αἰνεῖν αἶνον, faire un récit, ESCHL. <i>Ag. 1482 ;</i> donner un conseil, SOPH. <i>Ph. 1380 ; particul</i>. table, apologue, HÉS. <i>O. 200, ou</i> sentence, proverbe, EUR. <i>fr. 511 Nauck ;</i> THCR. <i>Idyl. 14, 43 ;</i><br><b> 2</b> louange, IL. <i>23, 265 ;</i> OD. <i>21, 110 ;</i> HDT. <i>7, 107 ;</i> SOPH. <i>O.C. 707 ;</i> chant funèbre, ESCHL. <i>Ag. 1547</i>.</p><p><b>➼</b> <i>En prose, seul</i>. HDT. <i>l. c</i>.<b>ἄϊνος</b> <b>ἄ·ϊνος, ος, ον</b> <font color=\"brown\">[ῑ]</font> sans fibres, TH. <i>H.P. 1, 5, 3</i>.</p><p><b>Étym</b>. ἀ, ἴς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αινος - αἶνος</font>\n<br><br>apparemment mot primaire: une histoire, mais utilisé dans le sens de </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G137":"<h1>Ainon</h1>\n<p>Strong n° 137 <i>Prononciation [ahee-nohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Enon (Angl. Aenon) = « sources »\n<ol><li>nom d'un lieu « proche de Salim » où Jean-Baptiste baptisait</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αινων</font> &lt; עינון - <font face=\"Georgia\">Αἰνών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G138":"<h1>haireomai</h1>\n<p>Strong n° 138 <i>Prononciation [hahee-reh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre pour soi, préférer, choisir</li>\n<li>choisir par vote, élire pour une fonction</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἱρέω</b> <b>αἱρέω-ῶ</b> <font color=\"darkgreen\">(<i>impf</i>. ᾕρουν, <i>f</i>. αἱρήσω ; <i>ao.2</i> εἷλον, <i>d’où impér</i>. ἕλε, <i>sbj</i>. ἕλω, <i>opt</i>. ἕλοιμι, <i>inf</i>. ἑλεῖν, <i>part</i>. ἑλών ; <i>pf</i>. ᾕρηκα ; <i>pass. f</i>. αἱρεθήσομαι ; <i>ao</i>. ᾑρέθην, <i>pf</i>. ᾕρημαι)</font><br><b>   I <i>act</i>.<br> 1</b> prendre dans ses mains, saisir : τι ἐν χερσί, μετὰ χερσίν <i>ou simpl</i>. χερσίν, OD. <i>4, 66, etc</i>. prendre qqe ch. avec ses mains : τινα κόμης, χερός, IL. <i>1, 197, 323,</i> qqn par les cheveux, par la main ; ἀχλὺν ἀπ' ὀφθαλμῶν, IL. <i>5, 127,</i> enlever les ténèbres des yeux ; τινά τι, IL. <i>16, 805,</i> enlever qqe ch. à qqn ; <i>abs. part</i>. ἑλών, ayant pris de force, par force, SOPH. <i>Ant. 497 ;</i><br><b> 2</b> prendre à la chasse <i>ou</i> à la guerre, capturer, IL. <i>21, 102, etc. ;</i> ζῶντας, XÉN. <i>An. 1, 6, 2,</i> faire des prisonniers (<i>litt</i>. prendre les hommes vivants) ; <i>p. ext</i>. s’emparer de : πόλιν, HDT. <i>1, 562,</i> THC. <i>2, 21 ;</i> SOPH. <i>Ph. 347, etc</i>. d’une ville ; χώραν, SOPH. <i>Tr. 240,</i> d’un pays ; tuer (<i>cf</i>. ἀναιρέω), EUR. <i>H.f. 994, d’où</i> triompher de : αἱρεῖ κακά, EUR. <i>El. 942,</i> (la vertu innée) triomphe des malheurs ; <i>p. anal</i>. στεφάνους, PD. <i>P. 3, 133</i>) κῦδος, IL. <i>17, 321,</i> remporter des couronnes, de la gloire ; δελεάσμασί τινα αἱρ. AR. <i>Eq. 786,</i> prendre qqn à l’appât ; <i>en parl. de l’intelligence :</i> αἱρ. τι, PLAT. <i>Phil. 17</i> e, POL. <i>282</i> d, <i>etc</i>. saisir, comprendre qqe ch. ; <i>en parl. des impressions phys. ou mor</i>. μηδέ τιν' ὕπνος αἱρείτω, IL. <i>10, 192,</i> que nul ne se laisse prendre par le sommeil ; ἐμὲ δέος ᾕρει, OD. <i>11, 633,</i> la crainte s’emparait de moi ; <i>de même</i> ἵμερος αἱρεῖ με, IL. <i>3, 446 ;</i> οἶκτος, EUR. <i>El. 968,</i> le désir, la pitié s’empare de moi ;<br><b> 3</b> saisir <i>ou</i> surprendre en flagrant délit : ἐπ' αὐτοφώρῳ ἑλεῖν, EUR. <i>Ion 1214,</i> prendre sur le fait ; φῶρα ἐπὶ κλοπῇ ἑλεῖν, PLAT. <i>Leg. 874</i> b, prendre un voleur en flagrant délit ; <i>d’où</i> convaincre : τινα δώρων, AR. <i>Nub. 591,</i> qqn de vénalité ; τινα κλέπτοντα, AR. <i>Eq. 834 ;</i> PLAT. <i>Leg. 941</i> d, qqn de vol ; <i>avec l’acc. du délit :</i> αἱρέω τὰ διαμαρτυρηθέντα, ISOCR. <i>374</i> b, convaincre de faux témoignage ; <i>avec un seul rég. de pers. :</i> τοῦτ' ἔστιν ὃ ἐμὲ αἱρήσει, PLAT. <i>Ap. 28</i> a, voilà ce qui va me perdre ; <i>d’où</i> αἱρ. δίκην <i>ou</i> γραφήν, ANT. <i>115, 24 ;</i> DÉM. <i>18, 3 ; 21, 181 Baiter-Sauppe,</i> avoir gain de cause ; οἱ ἑλόντες, DÉM. <i>518, 16,</i> ceux qui ont gain de cause, <i>p. opp. à</i> οἱ ἑαλωκότες ; <i>fig</i>. ὁ λόγος αἱρεῖ, PLAT. <i>Rsp. 604</i> c, la raison démontre <i>ou</i> prescrit ; αἱροῦντος λόγου, <i>avec l’inf</i>. PLAT. <i>Rsp. 440</i> b, quand la raison démontre que ; αἱρέει ἐμὴ γνώμη, HDT. <i>2, 43,</i> mon opinion me persuade que, <i>etc. ;</i><br><b>   II</b> <i>pass. :</i><br><b> 1</b> être pris, HDT. <i>1, 185, etc. (en ce sens, att</i>. ἁλίσκομαι) ; <i>fig</i>. être pris, être saisi : οὐδὲν εἰδὼς ὧν ὕφ' αἱρεθεὶς χρόνῳ δίκην δέδωκας, EUR. <i>El. 952,</i> toi qui ne prévoyais rien de cette punition sous l’atteinte de laquelle tu as enfin expié tes crimes ;<br><b> 2</b> être gagné, être remporté (<i>prix, victoire, etc</i>.) SOPH. <i>O.C. 1148 (en ce sens rare chez les Att</i>.) ;<br><b> 3</b> être choisi (<i>surt. à l’ao. et au pf</i>.) HDT. <i>7, 118, etc. ;</i> ESCHL. <i>Ag. 1209, etc. ;</i> αἱρεθεὶς ἑκών, EUR. <i>I.A. 1364</i> (il viendra) chargé de cette mission (<i>litt</i>. choisi pour remplir cette mission, mais cependant) de son plein gré ; στρατηγεῖν ᾑρημένος, XÉN. <i>Mem. 3, 2, 1,</i> élu général ; <i>rar. au près</i>. ARSTT. <i>Pol. 4, 15, 3 ;</i><br><b>   III</b> <i>moy. (f</i>. αἱρήσομαι ; <i>ao.2</i> εἱλόμην, <i>d’où impér</i>. ἑλοῦ, <i>sbj</i>. ἕλωμαι, <i>opt</i>. ἑλοίμην, <i>inf</i>. ἑλέσθαι, <i>part</i>. ἑλόμενος ; <i>pf</i>. ᾕρημαι, <i>v. ci-dessous</i>) :<br><b> 1</b> prendre pour soi <i>ou</i> qqe ch. à soi : τεύχεα, IL. <i>3, 338, etc. ;</i> δεῖπνον, XÉN. <i>Cyr. 8, 1, 13,</i> prendre ses armes, son repas ; ὕπνον, THC. <i>2, 75,</i> prendre son repos en dormant ;<br><b> 2</b> prendre de préférence, choisir, IL. <i>10, 235 ;</i> OD. <i>16, 149 ;</i> αἱρ. τὰ Ἀθηναίων, THC. <i>3, 63, ou</i> Ἀθηναίους, THC. <i>3, 56,</i> embrasser le parti des Athéniens ; αἱρ. γνώμην, HDT. <i>4, 137, 139,</i> adopter une opinion ; αἱρεῖσθαί τι πρό τινος, HDT. <i>1, 87 ;</i> XÉN. <i>Mem. 2, 5, 3, etc. ;</i> τι ἀντί τινος, XÉN. <i>An. 1, 7, 3 ;</i> DÉM. <i>22, 21 ;</i> ARSTT. <i>Nic. 9, 8 ;</i> τί τινος, SOPH. <i>Ph. 1100,</i> préférer une chose à une autre ; αἱρ. τι μᾶλλον ἤ, PLAT. <i>Ap. 38</i> e ; XÉN. <i>Ap. 9 ; ou simpl</i>. αἱρ. τι ἤ, XÉN. <i>Ages. 4, 5 ;</i> LYS. <i>196, 23 ;</i> THCR. <i>Idyl. 11, 49,</i> faire une chose plutôt qu’une autre ; μᾶλλον αἱρ. PLAT. <i>Ap. 38</i> e, <i>ou simpl</i>. αἱρ. <i>avec l’inf</i>. HDT. <i>1, 11,</i> préférer faire ; <i>abs</i>. αἱροῦμαι, ESCHL. <i>Ch. 551,</i> j’agrée ; <i>particul</i>. choisir par un vote, élire : τινα στρατηγόν, HDT. <i>6, 67 ;</i> THC. <i>8, 82 ;</i> δικαστήν, XÉN. <i>Cyr. 2, 4, 8 ;</i> ἄρχοντα, XÉN. <i>Cyr. 1, 5, 5,</i> élire qqn général, juge, chef ; αἱρ. τινα ἐπ' ἀρχήν, PLAT. <i>Leg. 809</i> a, <i>etc. ou</i> τινα ἄρχειν, PLAT. <i>Ap. 28</i> e, élire qqn pour commander.<p><b>➼</b> <i>Act. prés. ind. 3 sg. ion</i>. αἱρέει, HDT. <i>1, 132 ; 3 pl. ion</i>. αἱρέουσι, HDT. <i>8, 11. Impf. poét</i>. ᾕρεον, IL. <i>24, 579 ; épq</i>. ᾕρευν, HÉS. <i>Sc. 302 ; ion</i>. αἵρεον, HDT. <i>6, 31 ; 3 sg. ion</i>. αἵρεε, HDT. <i>5, 117, Fut. inf. poét</i>. αἱρησέμεν, IL. <i>18, 260. Ao.1 réc</i>. ᾕρησα, POLYEN <i>7, 39 ;</i> Ps.-CALLISTH. <i>1, 19 ; 2, 20 ; 3, 23. Ao.2 poét</i>. ἕλον, IL. <i>17, 321 ;</i> PD. <i>I. 7, 14 ; sbj. 3 sg. épq</i>. ἕλῃσι, IL. <i>23, 345 ; inf. poét</i>. ἑλέειν, IL. <i>15, 558. Ao. itér. 3 sg</i>. ἕλεσκε, IL. <i>24, 752. Pf. part. ion</i>. ἀραιρηκώς, HDT. <i>4, 66. Pl.q.pf. 3 sg</i>. ἀραιρήκεε, <i>ou, sel. d’autres,</i> αἱρήκεε, HDT. <i>3, 39. — Pass. ao. ion</i>. αἱρέθην, HDT. <i>3, 55, 159. Pf. part. ion</i>. ἀραιρημένα, HDT. <i>1, 185, etc. Pl.q.pf. 3 sg</i>. ἀραίρητο, HDT. <i>1, 191, 7, 3. Fut. ant</i>. ᾑρήσομαι, PLAT. <i>Prot. 388</i> b. — <i>Moy. prés. ion</i>. αἱρέομαι, HDT. <i>8, 63 ; part. ion</i>. αἱρεύμενοι, IL. <i>16, 353 ; éol</i>. αἰρεύμενος, HÉS. <i>O. 476. Impf. 3 sg. ion</i>. αἱρέετο, HDT. <i>1, 70 ; 5, 94. Fut</i>. αἱρήσομαι (<i>v. ci-dessus) ; fut. réc</i>. ἑλοῦμαι, DH. <i>4, 75 ;</i> SIB. <i>8, 184. Ao.2 poét</i>. ἑλόμην, IL. <i>19, 412 ; 2 sg. ion</i>. εἵλευ, HDT. <i>3, 52 ; impér. 2 sg</i>. ἑλεῦ (ἕλευ <i>Bkk</i>.) IL. <i>13, 294 ; 3 sg</i>. ἑλέσθω, IL. <i>9, 139 ; 3 pl</i>. ἑλέσθων, HDT. <i>8, 140. Ao.1 réc</i>. εἱλάμην, ANTH. <i>App. 257. Autre ao.1 réc</i>. ᾑρησάμην, <i>d’où sbj. 3 pl</i>. αἱρήσωνται, POL. <i>38, 5 (vulg</i>. -ήσονται <i>Bkk. Dind.). Pf. pass. au sens moy</i>. ᾕρημαι, XÉN. <i>An. 5, 6, 12 ;</i> AR. <i>Av. 1577 ;</i> DÉM. <i>22, 21. Pl.q.pf. pass. au sens moy. 3 pl</i>. ᾕρηντο, THC. <i>1, 62</i>.</p><p><b>Étym</b>. <i>inconnue</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιρεομαι - αἱρέωομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G139":"<h1>hairesis</h1>\n<p>Strong n° 139 <i>Prononciation [hah'-ee-res-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>action de prendre, capturer ex : prendre une ville</li>\n<li>choix, choisir</li>\n<li>ce qui est choisi</li>\n<li>ensemble d'hommes suivant leurs propres principes (secte, parti)\n<ol type=\"a\">\n<li>des Sadducéens</li>\n<li>des Pharisiens</li>\n<li>des Chrétiens</li>\n</ol>\n</li>\n<li>dissensions survenant de la diversité des opinions et buts</li>\n<li>division</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἵρεσις</b> <b>εως (ἡ) :<br>A</b> action de prendre : αἵρ. πόλεως, HDT. <i>4, 1 ;</i> THC. <i>2, 58, etc</i>. prise d’une ville ;<br><b>B</b> choix :<br><b>   I</b> <i>en gén</i>. αἵρεσιν διδόναι, ESCHL. <i>Pr. 779 ;</i> HDT. <i>1, 11, etc. ;</i> παραδιδόναι, PD. <i>N. 10, 82 ;</i> νέμειν, SOPH. <i>Aj. 265 ;</i> προτιθέναι τινί, PLAT. <i>Theæt. 196</i> c ; προϐάλλειν τινί, PLAT. <i>Gorg. 245</i> b, donner, laisser le choix à qqn ; αἵρεσιν λαμϐάνειν, DÉM. <i>947, 18,</i> avoir le choix ; ἔστι <i>ou</i> γίγνεταί μοι αἵρεσις, THC. <i>2, 61,</i> j’ai le choix ; οὐκ ἔχει αἵρεσιν, PLUT. <i>M. 708</i> b, cela n’admet pas de choix, il n’y a pas de choix ;<br><b>   II</b> <i>particul</i>. choix par un vote, élection, THC. <i>8, 89 ;</i> αἵρεσιν ποιεῖσθαι, ISOCR. <i>143</i> c, faire une élection ;<br><b>   III</b> <i>p. suite,</i> fonction élective, magistrature, PLAT. <i>Ax. 367</i> a ;<br><b>C</b> <i>p. suite,</i> préférence, inclination, goût particulier : πρός τινα, PHILIPP. (DÉM. <i>283, 12</i>) ; POL. <i>2, 61, 9,</i> pour qqn ; <i>d’où :</i><br><b>   I</b> recherche de : αἵρ. δυνάμεως, PLAT. <i>Gorg. 513</i> a, recherche du pouvoir ; <i>d’où</i> dessein, projet, PLAT. <i>Phædr. 256</i> c ; ESCHN. <i>29, 30 ;</i><br><b>   II</b> étude particulière de : αἵρ. Ἑλληνική, POL. <i>40, 6, 3,</i> étude des choses grecques ;<br><b>   III</b> préférence pour une doctrine, <i>d’où :</i><br><b> 1</b> école philosophique, POL. <i>5, 93, 8 ;</i> DH. <i>Amm. 1, p. 733, 2 ;</i> GAL. <i>1, 37 ;</i> SEXT. <i>41, 7 ; 361, 7 Bkk. ;</i><br><b> 2</b> école littéraire, DH. <i>5, 134, 3 Reiske, etc. ;</i><br><b> 3</b> école médicale, PHIL. <i>2, 475 ;</i> SEXT. <i>55, 5 Bkk. ;</i><br><b> 4</b> secte religieuse, NT. <i>Ap. 5, 17 ; 15, 5 ; 24, 5 ; 28, 22 ;</i> JOS. <i>A.J. 13, 5, 9 ; B.J. 2, 8, 1, etc. ; d’où</i> hérésie, CLÉM. <i>1, 812 ;</i> BAS. <i>4, 665 edd. Migne ;</i> οἱ ἀπὸ τῶν αἱρέσεων, CLÉM. <i>1, 989,</i> les hérésiarques ;<br><b> 5</b> parti politique, faction, NT. <i>1Cor. 11, 18 ; Gal. 5, 20 ; 2Petr. 2, 1 ;</i><br><b>   IV</b> motif du choix, condition proposée, proposition, DH. <i>3, 10 ;</i> DC. <i>74, 17</i>.<p><b>Étym</b>. αἱρέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιρεσις - αἵρεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (6)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G140":"<h1>hairetizo</h1>\n<p>Strong n° 140 <i>Prononciation [hahee-ret-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>choisir, élire</li>\n<li>appartenir à une secte</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἱρετίζω</b> <font color=\"darkgreen\">(<i>ao</i>. ᾑρέτισα, <i>pf</i>. ᾑρέτικα)</font> choisir, préférer, s’attacher à, <i>acc</i>. HPC. <i>1282, 20 ;</i> BABR. <i>61, 5 ;</i> SPT. <i>Gen. 3, 20 ; Num. 14, 8 ; 1Par. 28, 4 ; avec un inf</i>. SPT. <i>Judith, 11, 1 ; avec une prop. inf</i>. SPT. <i>1Par. 28, 6 ;</i><br><b><i>Moy</i></b>. <font color=\"darkgreen\">(<i>ao</i>. ᾑρετισάμην)</font> <i>m. sign</i>. CTÉS. <i>Pers. 9 ;</i> SPT. <i>Ps. 24, 13 ; 131, 14 ; 1 Macc. 2, 19 ; 9, 30 ;</i> NT. <i>Matth. 12, 18</i>.<p><b>Étym</b>. αἱρετός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιρετιζω - αἱρετίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G141":"<h1>hairetikos</h1>\n<p>Strong n° 141 <i>Prononciation [hahee-ret-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>capable de prendre ou choisir une chose</li>\n<li>factieux, qui suit une fausse doctrine</li>\n<li>hérétique</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἱρετικός</b> <b>ή, όν :<br>A</b> <i>act. :</i><br><b>   I</b> apte à choisir, qui choisit, <i>gén</i>. PLAT. <i>Def. 412</i> a ;<br><b>   II</b> homme de parti, <i>d’où :</i><br><b> 1</b> factieux, NT. <i>Tit. 3, 10 ;</i><br><b> 2</b> sectaire, hérétique, <i>en parl. de pers</i>. CLÉM. <i>1, 812 Migne ;</i> PORPH. <i>V. Plot. 66, 1 ; en parl. de choses (baptême, etc</i>.) CLÉM. <i>1, 813 Migne ;</i><br><b>B</b> <i>pass. t. d’astrol</i>. choisi <i>ou</i> désigné pour naître sous une constellation, PTOL.<p><b>Étym</b>. αἱρετός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιρετικος - αἱρετικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G142":"<h1>airo</h1>\n<p>Strong n° 142 <i>Prononciation [ah'-ee-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>élever, soulever, lever\n<ol type=\"a\">\n<li>depuis le sol : des pierres</li>\n<li>élever les mains</li>\n<li>sortir un poisson</li>\n</ol>\n</li>\n<li>transporter, porter, supporter</li>\n<li>transporter ce qui a été soulevé\n<ol type=\"a\">\n<li>déplacer d'un endroit</li>\n<li>s'approprier ce qui est pris</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἴρω</b> <font color=\"darkgreen\">(<i>impf</i>. ᾖρον, <i>f</i>. ἀρῶ <font color=\"brown\">[ᾰ]</font>, <i>ao</i>. ἦρα, <i>pf</i>. ἦρκα ; <i>pass. f</i>. ἀρθήσομαι, <i>ao</i>. ἤρθην, <i>d’où sbj</i>. ἄρθω, <i>opt</i>. ἀρθείην, <i>inf</i>. ἀρθῆναι, <i>part</i>. ἀρθείς ; <i>pf</i>. ἦρμαι)</font><br><b>   I</b> lever : ὑψόσ' ἀείρας (<i>épq</i>.) θῆκεν, IL. <i>10, 465,</i> ayant soulevé en l’air (pour les consacrer à Athèna, les dépouilles de Dolon), il les posa (au sommet d’un tamaris) ; ἄειρε (<i>épq</i>.) IL. <i>6, 264,</i> élève, <i>càd</i>. offre, présente ; αἴρ. τὴν χεῖρα, XÉN. <i>An. 5, 6, 33,</i> lever la main (pour voter) ; μηχανήν, θεούς, ANTIPH. (ATH. <i>222</i> c) lever la machine, les dieux, <i>càd</i>. les faire apparaître (au théâtre) ; <i>au pass</i>. être enlevé, <i>d’où</i> s’enlever : ἐς αἰθέρα ἀέρθη, OD. <i>19, 540,</i> il s’éleva dans l’éther, <i>en parl. d’un aigle ; d’où</i> être suspendu : πὰρ ξίφεος κουλεὸν ἄωρτο (μάχαιρα) IL. <i>3, 272,</i> près de la gaine de l’épée pendait un couteau ; <i>particul. :</i><br><b> 1</b> <i>t. milit. et de mar. :</i> τὰς ναῦς ἄραντες, THC. <i>1, 52,</i> ayant mis à la voile ; <i>abs</i>. αἴρ. lever l’ancre et mettre à la voile, THC. <i>4, 129 ; 8, 28, ou</i> lever le camp, décamper, <i>en parl. d’un chef d’armée,</i> THC. <i>2, 121 ; 2, 23, 98 ;</i> PLUT. <i>Popl. 22 ;</i><br><b> 2</b> lever pour apporter <i>ou</i> emporter : μή μοι οἶνον ἄειρε, IL. <i>6, 264,</i> ne m’offre pas de vin ; ᾔρετο τράπεζα, EUB. (ATH. <i>685</i> e) la table était dressée, <i>ou, au contr.,</i> ἀρθείσης τῆς τραπέζης, PLUT. <i>San. tu. p. 383</i>, la table enlevée ; μῆλα ἐξ Ἰθάκης ἄειραν νηυσί, OD. <i>21, 18,</i> ils emmenèrent les troupeaux d’Ithaque sur leurs navires ; <i>fig</i>. αἴρ. ἐκ πόλεως, PLAT. <i>Rsp. 578</i> e, chasser de la cité, exiler ;<br><b> 3</b> <i>p. suite,</i> enlever, supprimer, détruire, faire périr (<i>cf. lat</i>. tollere) SPT. <i>1Macc. 5, 2 ; Esaï. 57, 1 ;</i> NT. <i>Luc. 23, 18 ; Ap. 22, 22, etc. ;</i> DH. <i>2, 641, 4 Reiske ; d’où, avec un rég. de chose,</i> supprimer, faire cesser : ἆρον τὴν ἔκκλισιν ἀπό, <i>etc</i>. EPICT. <i>Ench. 2, 2,</i> retire ton aversion de, <i>etc. càd</i>. cesse de donner pour objet à ton aversion, <i>etc. ;</i><br><b> 4</b> <i>p. ext</i>. nier, réfuter, <i>p. opp. à</i> τίθημι, SEXT. <i>5, 1 Bkk. ;</i><br><b>   II</b> <i>fig</i>. faire une levée : στόλον, ESCHL. <i>Pers. 795,</i> lever l’équipage d’une flotte ;<br><b>   III</b> <i>fig</i>. élever, exalter, grandir : τινὰ ἐπαίνῳ ὑψηλὸν αἴρ. EUR. <i>Her. 322, ou</i> τινα αἴρ. εἰς ὕψος, EUR. <i>Ph. 409,</i> louer qqn et l’élever jusqu’aux nues ; αἴρ. τὸ πρᾶγμα λόγῳ, DÉM. <i>537, 43, ou</i> ἐπὶ μεῖζον αἴρ. LUC. exagérer l’affaire en la rapportant ; ἤρθη μέγας, DÉM. <i>20, 9 ;</i> AR. <i>Vesp. 1023,</i> on l’a grandi, exalté ;<br><b>   IV</b> mettre hors de soi ; <i>au pass</i>. être transporté : φόϐῳ, ESCHL. <i>Sept. 196,</i> de crainte ; <i>abs</i>. être excité, SOPH. <i>Ant. 111 ;</i><br><b><i>Moy</i></b>. <font color=\"darkgreen\">(<i>f</i>. ἀροῦμαι <font color=\"brown\">[α]</font>, <i>ao.1</i> ἠράμην, <i>pf</i>. ἦρμαι)</font><br><b> 1</b> lever sur sa tête <i>ou</i> sur ses épaules : φορτίον, DÉM. se charger d’un fardeau ; αἴρ. ἐπὶ τῶν ὤμων, ES. <i>90 b Halm,</i> soulever et charger sur ses épaules ;<br><b> 2</b> lever pour soi : ἱστούς, XÉN. <i>Hell. 6, 2, 29 ;</i> ἱστία, HDT. <i>8, 56, etc</i>. lever, hisser, larguer les voiles ;<br><b> 3</b> <i>fig</i>. soulever, exciter : νεῖκος, THGN. <i>90,</i> une querelle ; ἄρασθαι πόλεμον, ESCHL. <i>Suppl. 341 ;</i> HDT. <i>7, 132, etc. ;</i> THC. <i>4, 60, etc. ;</i> XÉN. <i>Cyr. 1, 6, 45, etc</i>. soulever <i>ou</i> entreprendre une guerre ;<br><b> 4</b> enlever, remporter : <i>fig</i>. νίκας, PD. <i>I. 6, 57,</i> des victoires ; κλέος, IL. <i>5, 3 ;</i> OD. <i>1, 240 ;</i> HÉS. <i>Sc. 107 ;</i> κῦδος, IL. <i>9, 303 ;</i> OD. <i>22, 253,</i> obtenir de la gloire.<p><b>➼</b> <i>Fut</i>. ἀρῶ <font color=\"brown\">[ᾰ]</font> SOPH. <i>Aj. 75 ;</i> LUC. <i>H. conscr. 14 (ne pas confondre avec le fut</i>. ἀρῶ <font color=\"brown\">[ᾱ]</font> <i>par contract. de</i> ἀερῶ, <i>v. ci-dessous). Ao</i>. ἦρα, <i>d’où impér</i>. ἆρον, SOPH. <i>Ph. 879 ; sbj. 2 sg</i>. ἄρῃς <font color=\"brown\">[ᾱ]</font> SOPH. <i>Aj. 129 ; opt. 2 sg</i>. ἄρειας <font color=\"brown\">[ᾱρ]</font> ESCHL. <i>Ch. 262 ; 3 pl</i>. ἄρειεν <font color=\"brown\">[ᾱ]</font> SIM. AM. <i>fr. 7, 60 Bgk ; inf</i>. ἆραι, CALL. <i>Cer. 35 ; part</i>. ἄρας <font color=\"brown\">[ᾱρ]</font> SOPH. <i>Tr. 795 ;</i> THC. <i>2, 12. Ao.1 réc. 3 pl</i>. ἤροσαν, SPT. <i>Jos. 3, 14. Pf. pass. au sens moy</i>. ἠρμένοι, SOPH. <i>El. 55 ;</i> STR. <i>150 ;</i> PHILSTR. <i>V. Ap. 3, 115 ; 6, 273. — Moy. fut. dor</i>. ἀρέομαι <font color=\"brown\">[ᾱ]</font> PD. <i>P. 1, 75. Ao.1</i> ἠράμην, <i>d’où dor</i>. ἀράμην <font color=\"brown\">[ᾱρ]</font> PD. <i>I. 6, 60 ; 2 sg</i>. ἤραο, <i>d’où les deux formes contr</i>. ἤρω, XÉNOPHAN. <i>5, 1, et béot</i>. ἤρα, AR. <i>Ach. 913 ; sbj</i>. ἄρωμαι <font color=\"brown\">[ᾱ]</font> SOPH. <i>Aj. 193 ; opt</i>. ἀραίμην <font color=\"brown\">[ᾱ]</font> EUR. <i>Cycl. 474 ; 3 sg</i>. ἄραιτο <font color=\"brown\">[ᾱ]</font> EUR. <i>Or. 3 ;</i> AR. <i>Ran. 1406 ; inf</i>. ἄρασθαι, THC. <i>6, 9, etc. ; part</i>. ἀράμενος <font color=\"brown\">[ᾱρ]</font> AR. <i>Ran. 32, Pax 763 ;</i> DÉM. <i>18, 208 Baiter-Sauppe, etc. À la conjug. de</i> αἴρω <i>on peut rapporter l’ao.2 moy. poét. (qqf. rattaché à</i> ἄρνυμαι) ἀρόμην <font color=\"brown\">[ᾰ]</font> IL. <i>11, 625 ; 23, 592 ; d’où sbj. 2 sg</i>. ἄρηαι, HÉS. <i>O. 632 ; 3 sg</i>. ἄρηται, IL. <i>12, 435 ;</i> PD. <i>N. 9, 46 ; opt</i>. ἀροίμην, IL. <i>18, 121 ;</i> ESCHL. <i>Sept. 316, etc. ; inf</i>. ἀρέσθαι, IL. <i>16, 88 ;</i> OD. <i>22, 253, etc. ; part</i>. ἀρόμενος, ESCHL. <i>Eum. 168. — Forme épq</i>. ἀείρω ; <i>impf</i>. ἤειρον ; <i>f</i>. ἀερῶ, <i>p. contr</i>. ἀρῶ <font color=\"brown\">[ᾱ]</font> ESCHL. <i>Pers. 795 ;</i> EUR. <i>I.T. 117, Suppl. 772, Her. 322, etc. ; ao</i>. ἤειρα, <i>d’où part. dor</i>. ἀείραις, PD. <i>fr. 88. Autre ao. sbj. 3 sg</i>. ἀέρσῃ, PANYAS. <i>fr. 6. Pf. inus. Pass. prés</i>. ἀείρομαι ; <i>impf</i>. ἠειρόμην, <i>3 pl. ion</i>. ἀείροντο, HDT. <i>8, 56 ; fut. inus. ; ao</i>. ἠέρθην (<i>d’où 3 pl. épq</i>. ἄερθεν, IL. <i>8, 74 ; sbj</i>. ἀερθῶ ; <i>part</i>. ἀερθείς), <i>pf</i>. ἤερμαι ; <i>pl.q.pf. 3 sg</i>. ἄωρτο (<i>p</i>. *ἤερτο) IL. <i>3, 272 ;</i> THCR. <i>Idyl. 24, 43. Moy. prés</i>. ἀείρομαι ; <i>impf. 3 duel</i> ἀειρέσθην, IL. <i>23, 501 ; fut. 3 sg</i>. ἀρεῖται <font color=\"brown\">[ᾱ]</font> (<i>contr. p</i>. *ἀερεῖται) EUR. <i>Hel. 1597 ; ao. impér</i>. ἀείραο, A. RH. <i>4, 476 ; part</i>. ἀειράμενος, IL. <i>23, 856 ;</i> OD. <i>15, 106, etc</i>.</p><p><b>Étym</b>. <i>contr. p</i>. ἀείρω, <i>p.-ê. R. indo-europ</i>. *h₂uer-, lever ; <i>p.-ê. à séparer d’une</i> R. *h²uer-, lier, <i>cf</i>. συναείρομαι, τετράορος, ἀρτάω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιρω - αἴρω</font>\n<br><br>racine primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n100 fois dans 96 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (19)</li>\n<li>Marc (20)</li>\n<li>Luc (20)</li>\n<li>Jean (26)</li>\n<li>Actes (9)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G143":"<h1>aisthanomai</h1>\n<p>Strong n° 143 <i>Prononciation [ahee-sthan'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apercevoir, percevoir, comprendre\n<ol type=\"a\">\n<li>par les sens (vue, toucher...)</li>\n<li>par l'esprit, comprendre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσθάνομαι</b> <font color=\"darkgreen\">(<i>impf</i>. ᾐσθανόμην, <i>f</i>. αἰσθήσομαι, <i>ao.2</i> ᾐσθόμην, <i>pf</i>. ᾔσθημαι)</font><br><b> 1</b> percevoir par les sens, HDT. <i>3, 87</i> (par l’odorat, XÉN. <i>Mem. 3, 11, 8 ;</i> par la vue, SOPH. <i>Ph. 75 ; surt</i>. par l’ouïe, THC. <i>6, 17 ;</i> SOPH. <i>Aj. 1318 ; p. opp. à</i> εἶδον, SOPH. <i>Ph. 445</i>) ; τι, SOPH. <i>ll. cc. ;</i> τινος, XÉN. <i>Hell. 4, 4, 4 ;</i> AR. <i>Nub. 292, etc</i>. qqe ch. (un bruit, un cri, <i>etc</i>.) ;<br><b> 2</b> percevoir par l’intelligence, s’apercevoir de, comprendre : τι, THC. <i>4, 70, etc., ou</i> τινος, EUR. <i>Tr. 633, etc</i>. qqe ch. ; αἰσθ. ὑπό τινος, THC. <i>5, 2,</i> apprendre de qqn ; <i>avec un gén. ou un acc. de pers. accompagné d’un part. :</i> ᾔσθησαί μου ψευδομαρτυροῦντος ; XÉN. <i>Mem. 4, 4, 11,</i> m’as-tu surpris rendant un faux témoignage ? εἰ λυπουμένην γ' αἴσθοιτό με, AR. <i>Pl. 1011,</i> s’il s’apercevait que j’ai du chagrin ; <i>avec une conj. ou un rel</i>. αἰσθ. ὅτι, PLAT. <i>Gorg. 518</i> e, <i>etc. ;</i> ὡς, XÉN. <i>An. 3, 1, 40 ;</i> ὁποῖον, XÉN. <i>Mem. 4, 4, 13 ;</i> πῶς, PLAT. <i>1 Alc. 135</i> c, <i>etc</i>. s’apercevoir <i>ou</i> comprendre que, quel, comment, <i>etc. ;</i> ἐπεὶ ᾔσθετο τὸ στράτευμα ὅτι, <i>etc</i>. XÉN. <i>An. 1, 2, 21,</i> lorsqu’il avait appris que l’armée, <i>etc. ;</i> ψυχὴ θεῶν ᾔσθηται ὅτι εἰσί, XÉN. <i>Mem. 1, 4, 13,</i> l’âme a le sentiment qu’il y a des dieux ; <i>avec un part. se rapportant au suj. :</i> ὁπότε τις αἴσθοιτο κάμνων, THC. <i>2, 51,</i> lorsqu’on se sentait atteint par le mal ; <i>abs</i>. comprendre, être intelligent, avoir conscience de soi, être en possession de ses facultés, THC. <i>5, 26 ;</i> οἱ αἰσθανόμενοι, THC. <i>1, 71,</i> les gens de bon sens.<p><b>➼</b> <i>Prés. opt. 3 pl. ion</i>. αἰσθανοίατο, AR. <i>Pax 209. Fut. pass. réc</i>. αἰσθανθήσομαι, SPT. <i>Esaï. 49, 26, et</i> αἰσθηθήσομαι, <i>Esaï. 33, 11. Ao. pass</i>. ᾐσθήθην, SPT. <i>Job 40, 18</i>.</p><p><b>Étym</b>. <i>R. indo-europ</i>. *h²eu-is-, percevoir ; <i>cf</i>. ἀΐω¹, <i>lat</i>. audiō, obœdiō.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισθανομαι - αἰσθάνομαι</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G144":"<h1>aisthesis</h1>\n<p>Strong n° 144 <i>Prononciation [ah'-ee-sthay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>perception, pas seulement par les sens, mais par l'intellect</li>\n<li>connaissance, discernement, intelligence\n<ol type=\"a\">\n<li>discernement moral dans l'éthique, tact</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἴσθησις</b> <b>εως (ἡ) :<br> 1</b> faculté de percevoir par les sens, sensation, EUR. <i>El. 291, etc. ; p. ext</i>. faculté de percevoir par l’intelligence, action de s’apercevoir, THC. <i>2, 4 ;</i> αἴσθησιν αἰσθάνεσθαι, PLAT. <i>Phædr. 240</i> c, <i>ou</i> λαμϐάνειν, PLAT. <i>Leg. 672</i> d, ISOCR. <i>12</i> c, <i>ou</i> λαμϐάνεσθαι, PLAT. <i>Rsp. 524</i> d, <i>ou</i> ἔχειν τινός, PLAT. <i>Ap. 40</i> c, avoir la sensation <i>ou</i> la perception de qqe ch. ; αἴσθησιν παρέχειν τινός, THC. <i>2, 50, ou</i> ποιεῖν, ANT. <i>134, 29 ;</i> DÉM. <i>133, 14,</i> faire voir <i>ou</i> comprendre à qqn, lui faire tomber sous le sens ;<br><b> 2</b> organe des sens, un des cinq sens, PLAT. <i>Phil. 39</i> b, <i>Rsp. 507</i> e ; ARSTT. <i>An. 2, 7 ; au pl</i>. les sens, PLAT. <i>Theæt. 156</i> b, <i>Hipp. mi. 374</i> d, <i>etc. ;</i><br><b> 3</b> piste d’un animal, XÉN. <i>Cyn. 3, 5</i>.<p><b>➼</b> <i>Mot de prose att. ; dans les Trag. seul</i>. EUR. <i>El. 288</i>.</p><p><b>Étym</b>. αἰσθάνομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισθησις - αἴσθησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G145":"<h1>aistheterion</h1>\n<p>Strong n° 145 <i>Prononciation [ahee-sthay-tay'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faculté de l'esprit de percevoir, comprendre, juger</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσθητήριον</b> <b>ου (τὸ)</b> organe de sensation, sens, HPC. <i>375, 44 ;</i> PLAT. <i>Ax. 366</i> a ; ARSTT. <i>An. 2, 9, 12, etc. ; au pl</i>. τὰ αἰσθ. NT. <i>Hebr. 5, 14 ; par crase</i> τᾀσθητήρια, MACH. (ATH. <i>346</i> a) les sens <i>ou</i> les facultés.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισθητηριον - αἰσθητήριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G146":"<h1>aischrokerdes</h1>\n<p>Strong n° 146 <i>Prononciation [ahee-skhrok-er-dace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ardent au gain, gourmand pour l'argent, par un vil intérêt, bassement intéressé, cupide, âpre au gain, avare</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσχροκερδής</b> <b>αἰσχρο·κερδής, ής, ές</b>, cupide <i>ou</i> avare, HDT. <i>1, 187 ;</i> EUR. <i>Andr. 451 ;</i> PLAT. <i>Rsp. 408</i> c ; ARSTT. <i>Nic. 4, 1, 43</i>.<br><i>● Sup</i>. -έστατος, AND. <i>4, 32 Baiter-Sauppe</i>.<p><b>Étym</b>. αἰ. κέρδος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισχρο-κεδης - αἰσχροκερδής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G147":"<h1>aischrokerdos</h1>\n<p>Strong n° 147 <i>Prononciation [ahee-skhrok-er-doce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>empressement pour le gain, par un vil intérêt, pour un gain sordide</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσχροκερδῶς</b> <i>adv</i>. avec cupidité <i>ou</i> avarice, NT. <i>1Petr. 5, 2</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισχροκερδως - αἰσχροκερδῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G148":"<h1>aischrologia</h1>\n<p>Strong n° 148 <i>Prononciation [ahee-skhrol-og-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>discussion infâme, discours obscène, vil propos, bas langage, grossièretés</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσχρολογία</b> <b>ας (ἡ) :<br> 1</b> propos honteux <i>ou</i> obscènes, XÉN. <i>Lac. 5, 6 ;</i> EPICT. <i>Ench. 33, 15 ;</i><br><b> 2</b> propos injurieux, POL. <i>8, 13, 8</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισρο-λογια - αἰσχρολογία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G149":"<h1>aischron</h1>\n<p>Strong n° 149 <i>Prononciation [ahee-skhron']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>honteux, bas, déshonorant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισκρον - αἴσχρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G150":"<h1>aischros</h1>\n<p>Strong n° 150 <i>Prononciation [ahee-skhros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>obscène, bassesse, déshonorer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσχρός</b> <b>ά, όν :<br>A</b> <i>intr. :</i><br><b>   I</b> <i>au phys. :</i><br><b> 1</b> laid, disgracieux, IL. <i>2, 216 ;</i> HH. <i>Ap. 197 ;</i> EUR. <i>1, 196 ;</i> PLAT. <i>Conv. 206</i> c, <i>etc. ; en parl. d’animaux,</i> XÉN. <i>Conv. 4, 19 ; 5, 7 ; Cyr. 3, 2, etc. ;</i><br><b> 2</b> difforme, HPC. <i>Art. 790 ;</i><br><b>   II</b> <i>au mor. :</i><br><b> 1</b> honteux, vil, infamant, HDT. <i>3, 155 ;</i> ESCHL. <i>Sept. 685 ;</i> SOPH. <i>El. 621, etc. ;</i> αἰσχρόν (ἐστι) <i>avec l’inf</i>. IL. <i>2, 298 ;</i> SOPH. <i>Aj. 473, etc</i>. c’est une honte de, <i>etc. ;</i> τὸ αἰσχρόν, la honte qui vient d’une mauvaise action, EPICT. <i>Ench. 24 ;</i> ἐν αἰσχρῷ θέμενος. EUR. <i>Hec. 806,</i> mettant parmi les choses honteuses, regardant comme honteux ; <i>chez les Stoïc</i>. τὸ καλὸν καὶ τὸ αἰσχρόν, le bien et le mal, la vertu et le vice ; <i>cf</i>. ARSTT. <i>Rhet. 1, 9, 1 ;</i><br><b> 2</b> qui ne convient pas, impropre : πρός τι, XÉN. <i>Mem. 3, 8, 7,</i> à qqe ch. ; καιρὸς αἰ. DÉM. <i>287, 25,</i> moment défavorable ;<br><b>B</b> <i>tr</i>. qui cause de la honte, déshonorant : αἰσχρὰ ἔπη, IL. <i>6, 325,</i> paroles outrageantes.<br><i>● Cp</i>. αἰσχίων, IL. <i>21, 437 ;</i> THC. <i>2, 40, 62, 97 ; 3, 63, etc. ;</i> PLAT. <i>Tim. 60</i> c, <i>1 Alc. 132</i> a, <i>etc. ; postér</i>. αἰσχρότερος, ARR. <i>● Sup</i>. αἴσχιστος, IL. <i>2, 216 ;</i> THC. <i>3, 59 ; 7, 68 ;</i> PLAT. <i>Leg. 663</i> b, <i>Gorg. 477</i> c ; <i>postér</i>. αἰσχρότατος, ATH.<p><b>➼</b> <i>Fém</i>. -ός, A. PL. <i>151</i>.</p><p><b>Étym</b>. <i>cf</i>. αἶσχος <i>et</i> αἰδώς.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισκρος - αἰσχρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G151":"<h1>aischrotes</h1>\n<p>Strong n° 151 <i>Prononciation [ahee-skhrot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>obscénité, paroles immondes, vilains mots</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσχρότης</b> <b>ητος (ἡ)</b> laideur, difformité, PLAT. <i>Gorg. 525</i> a.<p><b>Étym</b>. αἰσχρός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισκροτης - αἰσχρότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G152":"<h1>aischune</h1>\n<p>Strong n° 152 <i>Prononciation [ahee-skhoo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la confusion de celui qui est honteux</li>\n<li>ignominie, disgrâce, déshonneur</li>\n<li>être honteux d'une chose, honte d'une chose sexuelle (<a class=\"ref\" data-r=\"JUD1.13\">Jude 1.13</a> ; <a class=\"ref\" data-r=\"PHP3.19\">Php 3.19</a> ; <a class=\"ref\" data-r=\"REV3.18\">Ap 3.18</a>)\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσχύνη</b> <b>ης (ἡ)</b> <font color=\"brown\">[ῠ]</font> :<br><b> 1</b> l’honneur, THC. <i>2, 51 ; cf. 1, 34, etc. ;</i><br><b> 2</b> sentiment de honte, honte, pudeur : ὑπέρ τινος, DÉM. <i>43, 6 ;</i> ἐπί τινι, PLAT. <i>Conv. 178</i> d, honte de qqe ch. ; ὑπ' αἰσχύνης, ATT. par honte ; αἰσχύνην ἔχειν τινός, SOPH. <i>El. 616,</i> avoir honte de qqe ch. ; la Honte <i>ou</i> la Pudeur <i>personnifiée,</i> ESCHL. <i>Sept. 409 ;</i><br><b> 3</b> honte, déshonneur : αἰσχύνῃ πίπτειν, SOPH. <i>Tr. 597, ou</i> περιπίπτειν, XÉN. <i>Hell. 7, 3, 9,</i> tomber dans le déshonneur ; αἰσχύνην ἔχειν, THC. <i>1, 5,</i> causer du déshonneur (<i>p. opp. à</i> δόξαν φέρειν) ; αἰσχύνην φέρειν, SOPH. <i>Tr. 66 ;</i> ἐς αἰσχύνην φέρειν, HDT. <i>1, 10 ;</i> αἰσχύνην προσϐάλλειν <i>ou</i> περιάπτειν τινί, PLAT. <i>Leg. 878</i> c, <i>etc. ;</i> ἐν αἰσχύνῃ ποιεῖν τινα, DÉM. <i>272, 18,</i> déshonorer qqn ; ἐν αἰσχύναις ἔχειν τι, EUR. <i>Suppl. 164,</i> regarder qqe ch. comme honteux ;<br><b> 4</b> atteinte à l’honneur d’une femme, d’un enfant, <i>d’où</i> viol, relations intimes, <i>etc</i>. ISOCR. <i>64</i> d, <i>287</i> b ; DÉM. <i>19, 233 Baiter-Sauppe ; p. suite,</i> déshonneur d’une famille, PLAT. <i>Leg. 919</i> c.<p><b>Étym</b>. αἶσχος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισχυνη - αἰσχύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G153":"<h1>aischuno</h1>\n<p>Strong n° 153 <i>Prononciation [ahee-skhoo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>enlaidir</li>\n<li>déshonorer</li>\n<li>couvrir de honte, être honteux, avoir honte de, rougir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰσχύνω</b> <font color=\"darkgreen\">(<i>impf</i>. ᾔσχυνον, <i>f</i>. αἰσχυνῶ, <i>ao</i>. ᾔσχυνα, <i>pf. réc. non att</i>. ᾔσχυγκα)</font> <font color=\"brown\">[ῡ, <i>fut</i>. ῠ]</font> :<br><b>   I</b> enlaidir, défigurer : πρόσωπον, IL. <i>18, 24 ;</i> εἶδος, PD. <i>P. 4, 264,</i> défigurer le visage, la beauté ; κάλλος, LUC. <i>Im. 11,</i> souiller <i>ou</i> ruiner la beauté, défigurer ; <i>au pass</i>. ARSTT. <i>Pol. 5, 10, 7, etc. ;</i><br><b>   II</b> déshonorer :<br><b> 1</b> être une cause de déshonneur pour, <i>acc</i>. HDT. <i>9, 53 ;</i> ESCHL. <i>Ag. 401 ;</i> SOPH. <i>Aj. 1305 ;</i> PLAT. <i>Menex. 246</i> d ; αἰσχ. γένος πατέρων, IL. <i>6, 209,</i> déshonorer la race de ses ancêtres ;<br><b> 2</b> <i>particul</i>. déshonorer par des relations intimes : αἰσχ. λέχος, OD. <i>8, 269 ;</i> εὐνήν, ESCHL. <i>Ag. 1626,</i> souiller la couche ; <i>d’où abs</i>. déshonorer (une femme, des enfants, <i>etc</i>.) EUR. <i>El. 44 ;</i> ISOCR. <i>15, 251 Baiter-Sauppe ;</i> PLUT. <i>Eum. 9 ;</i><br><b> 3</b> discréditer, décrier, IL. <i>23, 571 ;</i> OD. <i>2, 86 ;</i> THC. <i>4, 92, etc</i>.<br><i>Pass.-moy. (f</i>. αἰσχυνοῦμαι, <i>rar</i>. αἰσχυνθήσομαι ; <i>ao</i>. ᾐσχύνθην, <i>pf. réc</i>. ᾔσχυμμαι) :<br><b> 1</b> avoir le sentiment de l’honneur, THC. <i>2, 43 ; cf. 5, 9, etc. ;</i><br><b> 2</b> avoir honte : τι, OD. <i>21, 323 ;</i> SOPH. <i>O.R. 1079 ;</i> PLAT. <i>Conv. 216</i> b ; τινι, AR. <i>Nub. 992 ;</i> LYS. <i>97, 12, etc. ;</i> ἐπί τινι, PLAT. <i>Rsp. 396</i> c ; XÉN. <i>Mem. 2, 2, 8 ;</i> ἔν τινι, THC. <i>2, 43 ;</i> ὑπέρ τινος, LYS. <i>142, 24 ;</i> ESCHN. <i>1, 26 Baiter-Sauppe ;</i> LUC. <i>Prom. 7, etc</i>. de qqe ch. ; τινα, EUR. <i>Ion 933 ;</i> XÉN. <i>An. 2, 3, 22 ;</i> PLAT. <i>Conv. 216</i> b ; πρός τινα, ARSTT. <i>Rhet. 2, 6, 1,</i> avoir honte devant qqn ; <i>abs</i>. OD. <i>7, 305 ; 18, 12 ;</i> HDT. <i>1, 10 ;</i> EUR. <i>Hipp. 1291 ; avec un inf</i>. HDT. <i>1, 82 ;</i> ESCHL. <i>Ag. 856 ;</i> PLAT. <i>Phædr. 257</i> d, <i>etc. ; avec un part</i>. λέγων οὐκ αἰσχυνεῖται, PLAT. <i>Phædr. 245</i> e, il ne rougira pas de parler ; <i>cf</i>. ESCHL. <i>Pr. 642 ;</i> SOPH. <i>Ant. 540 ; avec une prop. inf</i>. XÉN. <i>An. 2, 3, 22 ; avec</i> εἰ, XÉN. <i>Mem. 2, 10, 3 ;</i> DÉM. <i>1, 24 Baiter-Sauppe, etc. ; avec</i> ἤν, XÉN. <i>Œc. 21, 4 ; avec</i> μή, PLAT. <i>Theæt. 183</i> e.<p><b>➼</b> <i>Act. prés. inf. épq</i>. αἰσχυνέμεν, IL. <i>6, 209. Fut. ion</i>. αἰσχυνέω, HDT. <i>9, 53, Pf</i>. ᾔσχυκα, DRAC. <i>p. 12, 15, ou</i> ᾔσχυγκα, DC. <i>58, 16. Pl.q.pf</i>. ᾐσχύγκειν, DC. <i>77, 16. Pass. fut</i>. αἰσχυνθήσομαι, PHILÉM. (<i>Com. fr. 4, 53</i>) ; DIPH. (<i>ibid. 4, 421) ; d’ord. f. moy. au sens pass</i>. αἰσχυνοῦμαι, ESCHL. <i>Ag. 856 ;</i> AR. <i>fr. 21 ;</i> PLAT. <i>Tim. 49</i> d, <i>etc. Ao. inf. poét</i>. αἰσχυνθῆμεν, PD. <i>N. 9, 27. Pf. part. épq</i>. ᾐσχυμμένος, IL. <i>18, 180</i>.</p><p><b>Étym</b>. αἰσχύνη.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αισχυνω - αἰσχύνω</font>\n<br><br>vient de aischos (défigurer, c.à.d disgrâce)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Pierre (2)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G154":"<h1>aiteo</h1>\n<p>Strong n° 154 <i>Prononciation [ahee-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>demander, prier, appeler à, implorer, désirer, exiger, réclamer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰτέω</b> <b>αἰτέω-ῶ</b> <font color=\"darkgreen\">(<i>impf</i>. ᾔτουν, <i>f</i>. αἰτήσω, <i>ao</i>. ᾔτησα, <i>pf</i>. ᾔτηκα ; <i>pass</i>. αἰτηθήσομαι, <i>ao</i>. ᾐτήθην, <i>pf</i>. ᾔτημαι)</font><br><b> 1</b> demander : τι, IL. <i>5, 358 ;</i> OD. <i>17, 365, etc. ;</i> ATT. qqe ch. ; τινά τι, IL. <i>22, 295 ;</i> OD. <i>2, 387 ;</i> HDT. <i>3, 1 ;</i> ESCHL. <i>Ag. 1 ;</i> THC. <i>8, 85 ;</i> XÉN. <i>Cyr. 8, 3, 41, etc. ;</i> CIA. <i>2, 168, 34 (333 av. J.C.) ; v. Meisterh. p. 166, 8 ;</i> τι παρά τινος, XÉN. <i>An. 1, 3, 16 ;</i> PLAT. <i>Eryx. 398</i> e, <i>etc. ;</i> τι πρός τινος, THGN. <i>556,</i> qqe ch. à qqn ; τινί τι, HDT. <i>5, 17,</i> qqe ch. pour qqn ; τινα ποιεῖν, OD. <i>3, 173 ;</i> SOPH. <i>Ant. 65, etc</i>. à qqn de faire, <i>etc. ;</i> παρά τινος αἰτ. ὅπως, SPT. <i>Tob. 4, 19,</i> demander à qqn que ; <i>au pass</i>. αἰτούμενός τι, HDT. <i>8, 111 ;</i> THC. <i>8, 97 ;</i> PLAT. <i>Theæt. 146</i> d, <i>etc</i>. à qui l’on demande qqe ch. ;<br><b> 2</b> <i>t. de dial</i>. poser un postulatum, ARSTT. <i>Top. 8, 13, 2 ; An. pr. 1, 24, 2, etc. ;</i> ARR. <i>Epict. 1, 7, 22 ;</i><br><b><i>Moy</i></b>. <font color=\"darkgreen\">(<i>f</i>. αἰτήσομαι, <i>ao</i>. ᾐτησάμην)</font><br><b> 1</b> demander pour soi, <i>avec les mêmes construct. qu’à l’act.:</i> τι, HDT. <i>9, 54 ;</i> AR. <i>Nub. 1121,</i> qqe ch. ; τι παρά τινος, THCR. <i>Idyl. 17, 137,</i> qqe ch. à qqn ; <i>avec la prop. inf</i>. SOPH. <i>O.R. 880 ; avec un inf</i>. XÉN. <i>An. 2, 3, 18, etc. ; avec</i> ἵνα, JOS. <i>A.J. 14, 10, 17 ;</i> NT. <i>Col. 1, 9 ;</i> DC. <i>69, 16, 3, etc</i>. demander que, <i>etc. ;</i> αἰτ. τινα ὅπως, ANT. <i>112, 41,</i> demander à qqn que, <i>etc. ; abs. au part</i>. αἰτουμένῳ μοι δός, ESCHL. <i>Ch. 480,</i> accorde cela à ma prière ;<br><b> 2</b> demander, <i>en gén. :</i> ὑπέρ τινος, LYS. <i>141, 35,</i> pour qqn ;<br><b> 3</b> <i>t. de dial</i>. poser un postulatum, SEXT. <i>697, 15 ; 698, 31 Bkk</i>.<p><b>➼</b> <i>Impf. 1 sg. poét</i>. ᾔτεον, OD. <i>24, 336 ; 3 sg. poét</i>. ᾔτεε, IL. <i>22, 295, etc. ;</i> OD. <i>2, 387 ;</i> ᾔτεεν, IL. <i>5, 358 ; 1 pl. poét</i>. ᾐτέομεν, OD. <i>3, 173 ; impf. ion</i>. αἴτεον, HDT. <i>6, 113. Pass. part. prés. ion</i>. αἰτεόμενος, HDT. <i>8, 112, ou</i> αἰτεύμενος, THCR. <i>Idyl. 14, 63</i>.</p><p><b>Étym</b>. <i>cf</i>. αἴνυμαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιτεω - αἰτέω</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> - dénote une requête de la volonté\n<br><br> - une demande pour un besoin\n<br><br> - dénote la forme de la requête</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n71 fois dans 68 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Marc (10)</li>\n<li>Luc (11)</li>\n<li>Jean (11)</li>\n<li>Actes (10)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (1)</li>\n<li>1 Jean (5)</li>\n</ul>\n</td></tr>\n</table>","G155":"<h1>aitema</h1>\n<p>Strong n° 155 <i>Prononciation [ah'-ee-tay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pétition, requête, ce qui est exigé, la demande</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἴτημα</b> <b>ατος (τὸ) :<br> 1</b> demande, PLAT. <i>Rsp. 566</i> b ; SPT. <i>1Reg. 1, 17, etc. ;</i> NT. <i>Luc. 23, 24, etc. ;</i><br><b> 2</b> <i>t. de dial</i>. principe sans démonstration, postulatum, ARSTT. <i>An. post. 1, 10, 7</i>.<p><b>Étym</b>. αἰτέω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιτημα - αἴτημαw</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G156":"<h1>aitia</h1>\n<p>Strong n° 156 <i>Prononciation [ahee-tee'-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cause, raison, l'origine</li>\n<li>cause pour laquelle quelqu'un mérite une punition, crime, délit, faute</li>\n<li>coupable de crime, accusation, la plainte</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰτία</b> <b>ας (ἡ) :<br>   I</b> cause, motif, PD. <i>N. 7, 11, etc. ;</i> ATT. (THC. <i>7, 86 ;</i> PLAT. <i>Tim. 68</i> e, <i>etc</i>.) ; κοινοῦ τινος ἀγαθοῦ αἰτίᾳ, THC. <i>4, 87,</i> en vue d’un bien public ; αἰτία ἀνθ' ὅτου, EUR. <i>I.T. 926,</i> la raison pourquoi, <i>càd</i>. pour laquelle, <i>etc. ; avec le gén. de la pers. qui est cause de qqe ch.:</i> αἰτία θεοῦ, ESCHL. <i>Sept. 4,</i> un dieu en est cause ;<br><b>   II</b> imputation :<br><b> 1</b> <i>en mauv. part,</i> accusation, grief, blâme : αἰτίαν ἔχειν τινός, HDT. <i>5, 73 ;</i> ESCHL. <i>Eum. 579 ;</i> EUR. <i>El. 213,</i> etc. être accusé de qqe ch. ; αἰτίη ἔχει με, HDT. <i>5, 70,</i> je suis accusé de ; αἰτίαν ἔχειν ὑπό τινος, ESCHL. <i>Eum. 99 ;</i> THC. <i>6, 46 ;</i> PLAT. <i>Rsp. 565</i> b, <i>ou simpl</i>. αἰτίαν ἔχειν πρός τινος, SOPH. <i>Ant. 1312,</i> être accusé par qqn ; αἰτίαν ἔχειν <i>avec l’inf</i>. AR. <i>Vesp. 506 ; avec</i> ὅτι <i>ou</i> ὡς <i>et l’ind</i>. PLAT. <i>Ap. 38</i> c ; <i>avec ὡς et un part</i>. PLAT. <i>Phædr. 249</i> e, être accusé de, <i>etc. ;</i> ἐν αἰτίᾳ εἶναί <i>ou</i> γίγνεσθαί τινος, XÉN. <i>Cyr. 5, 3, 18 ;</i> αἰτίαν ὑπέχειν, XÉN. <i>Cyr. 6, 3, 16 ; Lac. 9, 5 ; ou</i> ὑπομένειν, ESCHN. <i>73, 24, ou</i> φέρεσθαι, THC. <i>2, 60 ;</i> εἰς αἰτίαν ἐμπίπτειν, PLAT. <i>Theæt. 150</i> a ; αἰτίαις περιπίπτειν, LYS. <i>108, 21, ou</i> ἐνέχεσθαι, PLAT. <i>Crit. 52</i> a, être accusé de, tomber sous le coup d’une accusation, être impliqué dans une accusation ; αἰτίαν λαμϐάνειν ἀπό τινος, THC. <i>2, 18,</i> encourir une accusation, un reproche au sujet de qqe ch. ; ἐν αἰτίᾳ τιθέναι, HDT. <i>8, 99, ou</i> ἔχειν τινά, HDT. <i>5, 106 ;</i> THC. <i>1, 35 ;</i> αἰτίαν νέμειν, SOPH. <i>Aj. 28 ;</i> ἐπάγειν, DÉM. <i>320, 9, ou</i> ἐπιφέρειν τινί, HDT. <i>1, 26 ;</i> THC. <i>5, 75, ou</i> εἴς τινα βάλλειν, EUR. <i>Tr. 305 ;</i> ἐν αἰτίᾳ βάλλειν τινά, SOPH. <i>O.R. 655,</i> accuser qqn, le mettre en accusation, lui intenter une accusation ; ἀπολύειν τινὰ τῆς αἰτίας, ESCHN. <i>3, 254 Baiter-Sauppe, ou</i> ἀπολύσασθαι, LYS. <i>13, 75 Baiter-Sauppe ;</i> ἀφιέναι τινὰ τῆς αἰτίας, LYS. <i>7, 8 Baiter-Sauppe,</i> décharger qqn d’une accusation ; ἐκτὸς αἰτίας κυρεῖς, ESCHL. <i>Pr. 330,</i> tu es à l’abri du reproche ;<br><b> 2</b> <i>en b. part,</i> ce qu’on impute à qqn, l’opinion qu’on a de qqn : αἰτίαν ἔχουσι βελτίους γεγονέναι, PLAT. <i>Gorg. 503</i> b, ils ont la réputation d’être devenus meilleurs ; ὧν πέρι αἰτίαν ἔχεις διαφέρειν, PLAT. <i>Theæt. 169</i> a, sur tout cela tu as la réputation d’exceller ;<br><b> 3</b> <i>p. suite,</i> catégorie, classe où l’on place qqe ch. DÉM. <i>645, 7</i>.<p><b>➼</b> <i>Ion</i>. -ίη, HDT. <i>ll. cc</i>.</p><p><b>Étym</b>. αἴτιος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιτια - αἰτίαw</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 20 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n<li>Actes (8)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G157":"<h1>aitiama</h1>\n<p>Strong n° 157 <i>Prononciation [ahee-tee'-am-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>accuser, apporter une charge contre, plainte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰτίαμα</b> <b>ατος (τὸ)</b> <font color=\"brown\">[ᾱμ]</font> sujet d’accusation, grief, ESCHL. <i>Pr. 194 ;</i> THC. <i>5, 72 ; au plur</i>. ESCHL. <i>Pr. 255</i>.<p><b>Étym</b>. αἰτιάω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιτιαμα - αἰτίαμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – accuser avec en première référence la base de l'accusation, le crime\n<br><br> – procéder à un assaut verbal qui atteint son but\n<br><br> – accuser formellement devant un tribunal, apporter publiquement une charge</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G158":"<h1>aition</h1>\n<p>Strong n° 158 Prononciation <i>[ah'-ee-tee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cause, faute, culpabilité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιτιον - αἴτιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G159":"<h1>aitios</h1>\n<p>Strong n° 159 <i>Prononciation [ah'-ee-tee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est la cause de toute chose\n<ol type=\"a\">\n<li>l'auteur\n<ol>\n<li>d'une cause, d'une œuvre</li>\n<li>d'un crime, d'une offense</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἴτιος</b> <b>α, ον :<br> 1</b> qui est la cause <i>ou</i> l’auteur de, responsable de : τινος, HDT. <i>1, 1,</i> de qqe ch. ; τινός τινι, LYS. <i>135, 10 ;</i> ISOCR. <i>179</i> c, de qqe ch. pour qqn ; <i>avec un inf. sans article :</i> αἴτ. θανεῖν, SOPH. <i>Ant. 1173,</i> qui est cause que qqn est mort ; <i>avec une prop. inf</i>. ANT. <i>132, 14 ;</i> τὸ αἴτιον, PLAT. <i>Crat. 413</i> a ; DÉM. <i>103, 17,</i> la cause ; τοῦτο αἴτιον ὅτι, PLAT. <i>Phæd. 110</i> e, cela est cause que ;<br><b> 2</b> coupable, accusé, IL. <i>1, 153, etc. ;</i> HDT. <i>7, 214 ;</i> THC. <i>4, 70 ;</i> τινος, HDT. <i>1, 45, 76 ; etc. ;</i> ESCHL. <i>Ch. 117 ;</i> SOPH. <i>Ph. 590, etc</i>. coupable <i>ou</i> accusé de qqe ch. ; τοῦ πατρὸς αἴτιοι, ESCHL. <i>Ch. 273,</i> coupables au sujet de leur père, responsables du meurtre de leur père ; ὁ αἴτ. ESCHL. <i>Ch. 68, etc</i>. l’accusé.<br><i>● Cp</i>. -ώτερος, THC. <i>4, 20 ;</i> XÉN. <i>Mem. 1, 6, 8, etc.</i> <i>● Sup</i>. -ώτατος, HDT. <i>6, 50 ;</i> THC. <i>1, 74, etc</i>.<p><b>➼</b> <i>Fém</i>. -ιος, AR. <i>Pl. 547</i>.</p><p><b>Étym</b>. <i>cf</i>. αἴνυμαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιτιος - αἴτιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G160":"<h1>aiphnidios</h1>\n<p>Strong n° 160 <i>Prononciation [aheef-nid'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>inattendu, soudain, imprévu, tout à coup, subit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰφνίδιος</b> <b>ος, ον</b> <font color=\"brown\">[ῐδ]</font> subit, soudain, ESCHL. <i>Pr. 680 ;</i> THC. <i>2, 61, etc. ;</i> τὸ αἰφνίδιον, PLUT. <i>Crass. 9 ;</i> LUC. <i>D. mort. 7, 2,</i> soudaineté ; <i>adv</i>. -ιον, PLUT. <i>Num. 15,</i> soudainement.<p><b>Étym</b>. αἴφνης.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιφνιδιος - αἰφνίδιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G161":"<h1>aichmalosia</h1>\n<p>Strong n° 161 <i>Prononciation [aheekh-mal-o-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>captivité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nαἰχμαλωσία <b>ας (ἡ)</b> :<br>captivité de guerre, captivité <i>en gén.</i><br><i><b><font color=\"brown\">Étym.</font></b></i> αἰχμάλωτος.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιχμαλωσια - αἰχμαλωσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G162":"<h1>aichmaloteuo</h1>\n<p>Strong n° 162 <i>Prononciation [aheekh-mal-o-tew'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rendre captif, garder captif, capturer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰχμαλωτεύω</b> <font color=\"brown\">[ᾰ]</font> <i>c</i>. αἰχμαλωτίζω SPT. <i>Gen. 14, 14 ; 34, 29 ; 1Reg. 30, 2, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιχμαλωτευω</font> &lt; שבית שבי - <font face=\"Georgia\">αἰχμαλωτεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G163":"<h1>aichmalotizo</h1>\n<p>Strong n° 163 <i>Prononciation [aheekh-mal-o-tid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>emmener au loin en captivité</li>\n<li>métaph. capturer les esprits, captiver</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰχμαλωτίζω</b> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> faire prisonnier de guerre, emmener en captivité, DS. <i>14, 37 ;</i> SPT. <i>Judith 5, 12 ; etc. ; au pass</i>. SPT. <i>Tob. 1, 10, etc. ;</i><br><b> 2</b> <i>fig</i>. captiver : ψυχήν, SPT. <i>Judith 16, 9,</i> l’âme (de qqn) ;<br><b><i>Moy</i></b>. <i>m. sign</i>. DS. <i>13, 24 ;</i> JOS. <i>B.J. 1, 22, 1 ; 4, 8, 1, etc</i>.<p><b>➼</b> <i>Part. pf. pass. au sens moy</i>. ᾐχμαλωτισμένοι, JOS. <i>B.J. 4, 9, 8</i>.</p><p><b>Étym</b>. αἰχμάλωτος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιχμαλωτιζω - αἰχμαλωτίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G164":"<h1>aichmalotos</h1>\n<p>Strong n° 164 <i>Prononciation [aheekh-mal-o-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être captif à la pointe de la lance, pris à la guerre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰχμάλωτος</b> <b>αἰχμ·άλωτος, ος, ον</b> <font color=\"brown\">[ᾰ]</font> :<br><b> 1</b> pris à la guerre (<i>litt</i>. à la pointe de la lance), HDT. <i>6, 79, etc. ;</i> ESCHL. <i>Ag. 1440 ;</i> SOPH. <i>Tr. 1417, etc. ; en parl. de choses (vaisseaux,</i> XÉN. <i>Hell. 2, 3, 8 ; richesses,</i> ESCHL. <i>Eum. 400, etc</i>.) ; οἱ αἰχμ. THC. <i>3, 70, etc</i>. les prisonniers de guerre ; τὰ αἰχμ. XÉN. <i>Hell. 4, 1, 26, etc</i>. le butin de guerre ;<br><b> 2</b> qui concerne un prisonnier de guerre, HDT. <i>9, 76 ;</i> αἰχμ. εὐνή, ESCHL. <i>Sept. 364,</i> couche d’une captive.<p><b>Étym</b>. αἰχμή, ἁλίσκομαι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιχμ-αλωτος - αἰχμάλωτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G165":"<h1>aion</h1>\n<p>Strong n° 165 <i>Prononciation [ahee-ohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pour toujours, perpétuité du temps, éternité, siècle, époque, temps, ère</li>\n<li>les mondes, l'univers</li>\n<li>période de temps, âge</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Αἰών</b> <b>(ὁ)</b> Æôn, <i>fils de Kronos,</i> EUR. <i>Her. 900 ;</i> Q. SM. <i>12, 194, etc</i>.<p><b>Étym</b>. <i>cf</i>. αἰών.<b>αἰών</b> <b>αἰῶνος (ὁ, <i>poét</i>. ἡ) :<br>   I</b> temps :<br><b> 1</b> durée de la vie, vie, IL. <i>5, 685, etc. ;</i> OD. <i>5, 160, etc. ;</i> τελευτᾶν τοῦ αἰῶνα, HDT. <i>1, 32, etc</i>. achever sa vie ; <i>p. suite,</i> vie <i>ou</i> destinée d’un homme, <i>d’où</i> destinée, sort : τὸ δὲ μετ' εὐτυχίαν κακοῦσθαι θνατοῖς βαρὺς αἰών, EUR. <i>I.T. 1121,</i> subir le malheur après la prospérité, voilà un sort pénible pour les mortels ;<br><b> 2</b> temps, éternité, ESCHL. <i>Eum. 553 ;</i> ἀπ' αἰῶνος, HÉS. <i>Th. 609,</i> depuis le commencement des âges ; δι' αἰῶνος, ESCHL. <i>Ag. 554, etc. ;</i> SOPH. <i>El. 1013,</i> dans le cours des âges ; εἰς τὸν αἰῶνα, SPT. <i>Ps. 118, 89 ;</i> εἰς αἰῶνα, SEXT. <i>406, 10 ; 638, 28 Bkk. ;</i> εἰς τοὺς αἰῶνας, SPT. <i>Sap. 3, 8 ;</i> εἰς ἅπαντα τὸν αἰῶνα, LYCURG. <i>162, 24, ou simpl</i>. τὸν ἅπ. αἰ. LYCURG. <i>155, 42 ;</i> ARSTT. <i>Cæl. 1, 19, 14, ou</i> τὸν αἰ. PLAT. <i>Tim. 37</i> d, de toute éternité, pour toujours ; <i>postér</i>. εἰς τὸν αἰῶνα τοῦ αἰῶνος, SPT. <i>Tob. 6, 18 ;</i> εἰς τοὺς αἰῶνας τῶν αἰώνων, NT. <i>Gal. 1, 5, litt</i>. pour l’éternité de l’éternité ; εἰς πάσας τὰς γενεὰς τοῦ αἰῶνος τῶν αἰώνων, NT. <i>Eph. 3, 21,</i> pour toutes les générations de toute éternité ;<br><b> 3</b> âge, génération, monde, ESCHL. <i>Sept. 774 ;</i> ὁ μέλλων αἰών, DEM. <i>295, 2,</i> les âges à venir, la postérité ; ὁ αἰ. οὗτος (<i>p. opp. à</i> ὁ μέλλων, l’avenir) NT. <i>Matth. 13, 22 ; Luc. 16, 8,</i> le temps présent ;<br><b>   II</b> moelle épinière, siège de la vie, HH. <i>Merc. 42, 119 ; etc. ;</i><br><b>   III</b> <i>t. de phil</i>. ce qui existe de toute éternité, entité divine, <i>p. opp. à</i> ἄνθρωπος, ARR. <i>Epict. 2, 5, 13</i>.</p><p><b>➼</b> ἡ αἰ. IL. <i>22, 58 ;</i> PD. <i>P. 4, 331 ;</i> EUR. <i>Ph. 1484, etc. Acc</i>. αἰῶνα ; <i>p. except</i>. αἰῶ, ESCHL. <i>Ch. 346</i>.</p><p><b>Étym</b>. <i>p</i>. *αἰϝών, <i>de indo-europ</i>. *h²ei-u-, durée de la vie, bien-être ; <i>cf</i>. αἰέν, αἰεί, οὐ, <i>lat</i>. ævum, juvenis.<b>ἀϊών</b> <b>όνος (ἡ)</b> <i>v</i>. ἠϊών.<b>ἀΐων</b> <b>ονος (ἡ)</b> <i>v</i>. ἠϊών.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιων - αἰών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n125 fois dans 100 versets de 22 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (4)</li>\n<li>Luc (7)</li>\n<li>Jean (13)</li>\n<li>Actes (2)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (8)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (1)</li>\n<li>Hébreux (15)</li>\n<li>1 Pierre (6)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>2 Jean (1)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (26)</li>\n</ul>\n</td></tr>\n</table>","G166":"<h1>aionios</h1>\n<p>Strong n° 166 <i>Prononciation [ahee-o'-nee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans commencement ni fin, ce qui a toujours été et qui sera toujours</li>\n<li>sans commencement</li>\n<li>sans fin, ne cessant jamais, éternel</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>αἰώνιος</b> <b>ος, ον :<br> 1</b> éternel, T. LOCR. <i>96</i> c ; PLAT. <i>Leg. 904</i> a, <i>etc. ;</i><br><b> 2</b> perpétuel, PLAT. <i>Rsp. 363</i> d ;<br><b> 3</b> séculaire : αἰώνιοι θέαι, HDN <i>3, 8, 18,</i> jeux séculaires, <i>à Rome</i>.<p><b>➼</b> <i>Fém</i>. -ία, PLAT. <i>Tim. 38</i> b ; <i>ion</i>. -ίη, ARÉT.</p><p><b>Étym</b>. αἰών.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αιωνιος - αἰώνιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – couvre l'idée philosophique complète – sans commencement ET sans fin ; également soit sans commencement OU sans fin ; par rapport au passé, ce mot est appliqué à ce qui a existé à une période trop loin pour l'esprit\n<br><br> – donne la prééminence à l'éternité incommensurable</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n70 fois dans 68 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (3)</li>\n<li>Luc (4)</li>\n<li>Jean (17)</li>\n<li>Actes (2)</li>\n<li>Romains (6)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (3)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (6)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (6)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G167":"<h1>akatharsia</h1>\n<p>Strong n° 167 <i>Prononciation [ak-ath-ar-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>impureté\n<ol type=\"a\">\n<li>physique : malpropreté</li>\n<li>dans un sens moral : l'impureté sensuelle, luxure, corruption, dépravation</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκαθαρσία</b> <b>ας (ἡ)</b> <font color=\"brown\">[κᾰ]</font> :<br><b>   I</b> <i>au pr. :</i><br><b> 1</b> malpropreté, HPC. <i>Fract. 772 ;</i><br><b> 2</b> impureté, souillure, PLAT. <i>Tim. 72</i> c ;<br><b>   II</b> <i>fig</i>. corruption, dépravation, DÉM. <i>553, 13</i>.<p><b>➼</b> <i>Ion</i>. -ίη, HPC. <i>l. c</i>.</p><p><b>Étym</b>. ἀκάθαρτος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακαθαρσια - ἀκαθαρσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G168":"<h1>akathartes</h1>\n<p>Strong n° 168 <i>Prononciation [ak-ath-ar'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>impureté, chose sale</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καθαρτης - ἀκαθάρτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G169":"<h1>akathartos</h1>\n<p>Strong n° 169 <i>Prononciation [ak-ath'-ar-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pas nettoyé, impur, impropre, sale, souillé\n<ol type=\"a\">\n<li>sens cérémonial : ce dont on doit s'abstenir par rapport à la loi lévitique</li>\n<li>sens moral : impur en pensée et en vie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκάθαρτος</b> <b>ἀ·κάθαρτος, ος, ον</b> <font color=\"brown\">[κᾰ]</font> :<br><b>   I</b> <i>pass</i>. non purifié, impur :<br><b> 1</b> <i>au pr</i>. HPC. <i>Aër. 283 ;</i> PLAT. <i>Leg. 866</i> a, <i>etc. ;</i> ARSTT. <i>Probl. 5, 27 ;</i><br><b> 2</b> <i>au mor</i>. PLAT. <i>Phæd. 81</i> b ;<br><b> 3</b> <i>au sens relig</i>. non purifié, non expié, SOPH. <i>O.R. 256 ;</i> PLAT. <i>Leg. 854</i> b ;<br><b>   II</b> <i>act</i>. impropre à purifier, ARÉT. <i>Cur. m. diut. 1, 8</i>.<br><i>● Cp</i>. -ότερος, PLAT. <i>Phil. 52</i> d ; ARÉT. <i>l. c</i>.<p><b>Étym</b>. ἀ, καθαίρω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακαθαρτος - ἀκάθαρτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n30 fois dans 29 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (11)</li>\n<li>Luc (6)</li>\n<li>Actes (5)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G170":"<h1>akaireomai</h1>\n<p>Strong n° 170 <i>Prononciation [ak-ahee-reh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>manquer d'occasion, d'opportunité, ne pas avoir l'occasion</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καιρεομαι - ἀκαιρέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G171":"<h1>akairos</h1>\n<p>Strong n° 171 <i>Prononciation [ak-ah'-ee-roce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>qui parle ou agit à contre-temps, importun, fâcheux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκαίρως</b> <i>adv</i>. à contre-temps, ESCHL. <i>Ch. 624, etc. ;</i> HPC. <i>V. med. 11, etc</i>.<br><i>● Cp</i>. -οτέρως, HPC. <i>Acut. 955</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καιρωος - ἀκαίρως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G172":"<h1>akakos</h1>\n<p>Strong n° 172 <i>Prononciation [ak'-ak-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans artifice ou fraude, inoffensif, libre de culpabilité, sans méchanceté, sans malice, simple, ingénu</li>\n<li>ne craignant pas le mal de la part des autres, innocent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄκακος</b> <b>ἄ·κακος, ος, ον</b> <font color=\"brown\">[κᾰ]</font> :<br><b> 1</b> sans méchanceté, ESCHL. <i>Pers. 664 ;</i> PLAT. <i>Tim. 91</i> d ;<br><b> 2</b> sans malice, ingénu, simple, DÉM. <i>1153, 11 ; 1164, 13 ;</i> ANAXIL. (ATH. <i>254</i> c).<p><b>Étym</b>. ἀ, κακός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κακος - ἄκακος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G173":"<h1>akantha</h1>\n<p>Strong n° 173 <i>Prononciation [ak'-an-thah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>épine, ronce, piquant,</li>\n<li>buisson, bruyère, une plante épineuse, chardon</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄκανθα</b> <b>ης (ἡ)</b> <font color=\"brown\">[ᾰκ]</font> :<br><b>   I</b> épine, piquant, ARSTT. <i>P.A. 2, 9, 2 ;</i> THCR. <i>Idyl. 7, 140 ; en parl. d’épines de roses,</i> LUC. <i>H. conscr. 28, etc. ; d’où n. de plantes épineuses :</i><br><b> 1</b> chardon, SOPH. <i>fr. 643 ; plur</i>. OD. <i>5, 328 ;</i><br><b> 2</b> acacia d’Égypte (<i>mimosa Nilotica</i> L.) HDT. <i>2, 96 ;</i><br><b> 3</b> acanthe (<i>cf</i>. ἄκανθος) DIOSC. <i>1, 77 ; 3, 14, etc. ;</i><br><b>   II</b> <i>p. anal. en parl. du corps de l’homme ou des animaux :</i><br><b> 1</b> piquant d’un porc-épic, ARSTT. <i>H.A. 4, 5 ;</i><br><b> 2</b> arête de poisson, ESCHL. <i>fr. 270 ;</i> ANTIPH. (ATH. <i>339</i> a) ; AR. <i>Vesp. 969 ;</i><br><b> 3</b> épine dorsale, HDT. <i>2, 75 ; 4, 72 ;</i> HPC. <i>Art. 791 ;</i> EUR. <i>El. 492 ;</i> THCR. <i>Idyl. 24, 32, etc. ;</i><br><b>   III</b> <i>fig</i>. difficulté épineuse, ATH. <i>97</i> d ; LUC. <i>Hes. 5</i>.<p><b>➼</b> <i>Se rencontre dans une inscr. att. du 5<sup>e</sup> siècle,</i> CIA. <i>1, 324, c, 2, 5 (408 av. J.C.) ; v. Meisterh. p. 93, 3</i>.</p><p><b>Étym</b>. <i>probabl. pré-grec</i>.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακανθα - ἄκανθα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (3)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G174":"<h1>akanthinos</h1>\n<p>Strong n° 174 <i>Prononciation [ak-an'-thee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>épineux, fait avec des brindilles de plante épineuse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκάνθινος</b> <b>η, ον</b> <font color=\"brown\">[ᾰκ]</font> :<br><b> 1</b> rempli d’épines, ANACR. <i>58, 12 ;</i><br><b> 2</b> fait d’épines, NT. <i>Marc. 15, 17 ; Joh. 19, 5 ;</i><br><b> 3</b> fait de bois d’acacia, HDT. <i>2, 96, ou</i> de l’écorce d’une sorte de chardon, STR. <i>175</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακανθινος - ἀκάνθινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G175":"<h1>akarpos</h1>\n<p>Strong n° 175 <i>Prononciation [ak'-ar-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>métaph. sans fruit, stérile, ne produisant pas ce qui est prévu, inutile</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄκαρπος</b> <b>ἄ·καρπος, ος, ον :<br>   I</b> <i>intr. :</i><br><b> 1</b> qui ne donne pas de fruits, stérile, EUR. <i>fr. 890, 8 Nauck ;</i> PLAT. <i>Tim. 91</i> c ; λίμνη ἄ. ἰχθύων, PAUS. <i>5, 7, 3,</i> lac <i>ou</i> étang sans poisson ;<br><b> 2</b> <i>fig</i>. sans profit, stérile, vain, PLAT. <i>Phædr. 277</i> a ; ARSTT. <i>Nic. 4, 3, 33, etc. ;</i><br><b>   II</b> <i>tr</i>. qui rend stérile, ESCHL. <i>Eum. 942</i>.<p><b>Étym</b>. ἀ, καρπός.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καρπος - ἄκαρπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Tite (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G176":"<h1>akatagnostos</h1>\n<p>Strong n° 176 <i>Prononciation [ak-at-ag'-noce-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui ne peut être condamné, ni censuré, inattaquable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκατάγνωστος</b> <b>ἀ·κατάγνωστος, ος, ον :<br> 1</b> non condamné, acquitté, SPT. <i>2Macc. 4, 47 ;</i><br><b> 2</b> non condamnable, NT. <i>Tit. 2, 8</i>.<p><b>Étym</b>. ἀ, καταγιγνώσκω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καταγνωστος - ἀκατάγνωστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G177":"<h1>akatakaluptos</h1>\n<p>Strong n° 177 <i>Prononciation [ak-at-ak-al'-oop-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non couvert, non voilé, dévoilé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκατακάλυπτος</b> <b>ἀ·κατακάλυπτος, ος, ον</b> <font color=\"brown\">[ᾰλ]</font> non voilé, non couvert, POL. <i>15, 27, 2 ;</i> SPT. <i>Lev. 13, 45 ;</i> NT. <i>1Cor. 11, 5 et 13</i>.<p><b>Étym</b>. ἀ, κατακαλύπτω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κατακαλυπτος - ἀκατακάλυπτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT).\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G178":"<h1>akatakritos</h1>\n<p>Strong n° 178 <i>Prononciation [ak-at-ak'-ree-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non condamné, puni sans être jugé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκατάκριτος</b> <b>ἀ·κατάκριτος, ος, ον</b>, non condamné, NT. <i>Ap. 16, 37 ; 22, 25</i>.<p><b>Étym</b>. ἀ, κατακρίνω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κατακριτος - ἀκατάκριτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G179":"<h1>akatalutos</h1>\n<p>Strong n° 179 <i>Prononciation [ak-at-al'-oo-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>indissoluble, non sujet à la destruction, impérissable, indestructible</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκατάλυτος</b> <b>ἀ·κατάλυτος, ος, ον</b> <font color=\"brown\">[ῠ]</font> indissoluble, DH. <i>10, 31 ;</i> NT. <i>Hebr. 7, 16</i>.<p><b>Étym</b>. ἀ, καταλύω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καταλυτος - ἀκατάλυτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G180":"<h1>akatapaustos</h1>\n<p>Strong n° 180 <i>Prononciation [ak-at-ap'-ow-stos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>incapable d'arrêter, incessant, qui commet continuellement</li>\n<li>ce qui ne peut être tranquillisé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκατάπαυστος</b> <b>ἀ·κατάπαυστος, ος, ον :<br> 1</b> incessant, sans fin, POL. <i>4, 17, 4 ;</i> ἀ. ἀρχή, PLUT. <i>Arat. 26,</i> pouvoir à vie ; <i>avec un gén</i>. ἀ. ἁμαρτίας, NT. <i>2Petr. 2, 14,</i> qui ne cesse pas de pécher ;<br><b> 2</b> qu’on ne peut faire cesser, irrésistible, DS. <i>11, 67</i>.<p><b>Étym</b>. ἀ, καταπαύω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καταπαυστος - ἀκατάπαυστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G181":"<h1>akatastasia</h1>\n<p>Strong n° 181 <i>Prononciation [ak-at-as-tah-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>instabilité, un état de désordre, dérangement, confusion,</li>\n<li>agitation, émeute, soulèvement, bouleversement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκαταστασία</b> <b>ας (ἡ)</b> <font color=\"brown\">[στᾰ]</font> :<br><b> 1</b> instabilité, mobilité de caractère, POL. <i>7, 4, 8 ;</i><br><b> 2</b> agitation, bouleversement, POL. <i>1, 70, 1 ; 31, 13, 6 ;</i> SPT. <i>Tob. 4, 13 ; Prov. 26, 28 ;</i> NT. <i>Luc. 21, 9</i>.<p><b>Étym</b>. ἀκατάστατος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καταστασια - ἀκαταστασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G182":"<h1>akatastatos</h1>\n<p>Strong n° 182 <i>Prononciation [ak-at-as'-tat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>instable, inconstant, inquiet, agité, troublé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκατάστατος</b> <b>ἀ·κατάστατος, ος, ον</b> <font color=\"brown\">[στᾰ]</font> :<br><b> 1</b> non au repos, agité, troublé, DÉM. <i>19, 136 ;</i> DH. <i>6, 74 ; en parl. de fièvres,</i> intermittent, irrégulier, HPC. <i>399, 47 ;</i><br><b> 2</b> qui ne laisse pas de sédiment, de dépôt, HPC.<p><b>Étym</b>. ἀ, καθίστημι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-καταστατος - ἀκατάστατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G183":"<h1>akataschetos</h1>\n<p>Strong n° 183 <i>Prononciation [ak-at-as'-khet-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>qu'on ne peut pas faire tenir tranquille, incoercible</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκατάσχετος</b> <b>ἀ·κατάσχετος, ος, ον</b>, qu’on ne peut contenir, Ps.-PHOCYL. <i>96 ;</i> DS. <i>16, 10 ; 17, 38 ;</i> PLUT. <i>Mar. 44 ;</i> SPT. <i>Job 31, 11 ; 3 Macc. 6, 17, etc</i>.<p><b>Étym</b>. ἀ, κατέχω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κατασχετος - ἀκατάσχετος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G184":"<h1>Akeldama</h1>\n<p>Strong n° 184 <i>Prononciation [ak-el-dam-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Hakeldama (Angl. Aceldama) = « Champ du Sang » (ou champ du sommeil)\n<ol><li>un champ acheté avec l'argent de la trahison, proche de Jérusalem</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ακελδαμα</font> &lt; חקל דמא - <font face=\"Georgia\">Ἀκελδαμά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G185":"<h1>akeraios</h1>\n<p>Strong n° 185 <i>Prononciation [ak-er'-ah-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>non mélangé, pur (tel du vin ou des métaux)</li>\n<li>esprit sans mélange de mal, libre d'artifice, innocent, simple</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκέραιος</b> <b>ἀ·κέραιος, ος, ον :<br> 1</b> non mélangé, pur, <i>en parl. d’eau,</i> ARSTT. <i>H.A. 8, 24 ; en parl. de pers. d’un sang pur,</i> EUR. <i>Ph. 943 ;</i><br><b> 2</b> non entamé, entier, intact : ἀκ. πόλις, HDT. <i>3, 146 ;</i> γῆ, THC. <i>2, 18,</i> ville <i>ou</i> territoire qui n’a pas souffert ; ἀκ. δύναμις, THC. <i>3, 3,</i> troupe fraîche, armée dans toute sa force ; λέχος ἀκ. EUR. <i>Hel. 48,</i> couche inviolée ; οὐσία ἀκ. DÉM. <i>1087, 24,</i> fortune intacte ; <i>fig</i>. ἀκ. ἐλπίδες, POL. <i>6, 9, 3,</i> espérances intactes ; <i>en parl. de pers</i>. non souillé, EUR. <i>Or. 922 ; avec un gén</i>. ἀκ. τινος, PLAT. <i>Rsp. 409</i> a, non souillé par qqe ch. ; ἐξ ἀκεραίου, à nouveau, POL. <i>24, 4, 10, ou</i> dans une situation entière, POL. <i>6, 24, 9 ;</i> ἐν ἀκεραίῳ ἐᾶν, POL. <i>2, 2, 10,</i> laisser en l’état.<p><b>Étym</b>. ἀ, κεράννυμι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κεραιος - ἀκέραιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Romains (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G186":"<h1>aklines</h1>\n<p>Strong n° 186 <i>Prononciation [ak-lee-nace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui ne vacille pas, qui ne fléchit pas, ferme, inamovible</li>\n<li>qui ne penche pas, droit</li>\n<li>fixe, immobile</li>\n<li>horizontal</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκλινής</b> <b>ἀ·κλινής, ής, ές</b> <font color=\"brown\">[ῐ]</font> :<br><b> 1</b> qui ne penche pas, droit, PLAT. <i>Phæd. 109</i> a ; ANTH. <i>10, 11 ; p. suite,</i> ferme, NONN. <i>D. 7, 331 ; fig</i>. ferme, stable, ANTH. <i>12, 158 ;</i> LUC. <i>Dem. enc. 43 ;</i><br><b> 2</b> fixe, immobile, NONN. <i>D. 35, 11 ;</i><br><b> 3</b> horizontal, HÉRON <i>244</i>.<br><i>● Cp</i>. -έστερος, SYN. <i>Ep. 56, 191</i> b.<p><b>Étym</b>. ἀ, κλίνω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κλινης - ἀκλινής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G187":"<h1>akmazo</h1>\n<p>Strong n° 187 <i>Prononciation [ak-mad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prospérer, fleurir, arriver à maturité, à l'échéance, être mur (grappe)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκμάζω</b> être au plus haut point, <i>càd</i>. dans toute sa force, sa fraîcheur, sa maturité, <i>abs. en parl. de pers</i>. HDT. <i>2, 134 ;</i> PLAT. <i>Prot. 335</i> e, <i>etc. ; en parl. de choses :</i> ῥώμη ἀκμάζουσα, ANT. <i>127, 25,</i> force dans tout son développement ; ἀκμάζοντος τοῦ πολέμου, THC. <i>3, 3,</i> la guerre étant dans toute sa force ; τὰ πράγματα ἤκμαζε, HDT. <i>3, 57,</i> les affaires étaient au plus haut point de prospérité ; <i>avec le dat. ou l’acc.:</i> ἀ. ῥώμῃ, PLAT. <i>Pol. 310</i> d, être dans la plénitude de la force ; <i>avec</i> ἐν <i>et le dat</i>. ESCHN. <i>46, 23 ;</i> PLUT. <i>Per. 37 ;</i> ἀ. ἔς τι, THC. <i>1, 1,</i> déployer toutes ses ressources, être ardent pour qqe ch. : <i>avec un inf</i>. XÉN. <i>An. 3, 1, 25,</i> avoir toute la force nécessaire pour faire qqe ch. ; <i>impers</i>. il est temps de : ἀκμάζει βρετέων ἔχεσθαι, ESCHL. <i>Sept. 94,</i> le moment est venu d’embrasser les statues (des dieux).<p><b>Étym</b>. ἀκμή.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακαμαζω - ἀκμάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G188":"<h1>akmen</h1>\n<p>Strong n° 188 <i>Prononciation [ak-mane']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un point</li>\n<li>extrémité, comble, apogée, le plus haut degré, le plus haut point</li>\n<li>le temps présent, le moment opportun, l'occasion, l'instant même</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακμην - ἀκμήν</font>\n<br><br>accusatif du nom « un comble »</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G189":"<h1>akoe</h1>\n<p>Strong n° 189 <i>Prononciation [ak-o-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le sens de l'ouïe</li>\n<li>l'organe de l'ouïe, l'oreille</li>\n<li>la chose entendue\n<ol type=\"a\">\n<li>instruction, faite oralement\n<ol>\n<li>de la prédication de l'évangile, écoute de la parole</li>\n</ol>\n</li>\n<li>ouï-dire, bruit ou rumeur, nouvelle, renommée</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκοή</b> <b>ῆς (ἡ)</b> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> ouïe, <i>l’un des cinq sens,</i> HDT. <i>1, 38 ; joint à</i> ὄψις, PLAT. <i>Phæd. 65</i> b, <i>Theæt. 185</i> c ; <i>au plur. joint à</i> ὄψις, PLAT. <i>Theæt. 156</i> b, <i>etc. ;</i><br><b>   II</b> oreille, organe de l’ouïe, HERMIPP. (<i>Bkk. 369</i>) ; PHÉRÉCR. (ATH. <i>649</i> c) ; δυσὶν ἀκοαῖς κρίνειν, ARSTT. <i>Pol. 3, 16, 12,</i> décider avec les deux oreilles ; τὰς ἀκοὰς ἀνατιθέναι τινί, POL. <i>24, 5, 9,</i> prêter l’oreille à qqe récit ;<br><b>   III</b> action d’écouter, d’entendre, <i>d’où :</i><br><b> 1</b> audition : ἀκοῆς ἄξιος, PLAT. <i>Theæt. 142</i> d, digne d’être écouté ; εἰς ἀκοὴν φωνῆς, DS. <i>19, 41,</i> aussi loin que la voix peut être entendue ;<br><b> 2</b> <i>p. suite, fig</i>. obéissance, SPT. <i>1Reg. 15, 22 ;</i><br><b>   IV</b> ce qu’on entend : récit, bruit, tradition, ouï-dire, PD. <i>P. 1, 162 ;</i> EUR. <i>Ph. 819 ;</i> PLAT. <i>Epin. 985</i> c, <i>Criti. 109</i> c, <i>Leg. 798</i> b ; ἐκ παλαιᾶς ἀκοῆς, PLAT. <i>Tim. 23</i> c, d’après une ancienne tradition ; <i>au plur</i>. τὰς ἀκοὰς τῶν προγεγενημένων, THC. <i>1, 20,</i> la tradition des événements antérieurs ; ἀκοῇ ἱστορεῖν, HDT. <i>2, 29,</i> raconter par ouï-dire : ἀκοῇ ἐπίστασθαι, ANT. <i>137, 17 (cf</i>. THC. <i>4, 126</i>) savoir par ouï-dire ; ἐξ ἀκοῆς λέγειν, PLAT. <i>Phæd. 61</i> d, parler par ouï-dire ; <i>avec le gén. de la pers. d’où vient le bruit :</i> ἀκοῇ Ἠλέκτρας, EUR. <i>I.T. 811,</i> pour l’avoir entendu dire à Électre.<p><b>➼</b> <i>Dor</i>. ἀκοά, PD. <i>P. l. c., etc</i>.</p><p><b>Étym</b>. <i>p</i>. *ἀκοϝή ; <i>cf</i>. ἀκουή <i>et</i> ἀκούω.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακοη - ἀκοή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 22 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G190":"<h1>akoloutheo</h1>\n<p>Strong n° 190 <i>Prononciation [ak-ol-oo-theh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>suivre celui qui précède, se joindre à sa suite, accompagner</li>\n<li>se joindre comme disciple, devenir ou être un disciple\n<ol type=\"a\">\n<li>faire partie de son groupe</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκολουθέω</b> <b>ἀκολουθέω-ῶ</b> <font color=\"darkgreen\">(<i>f</i>. -ήσω, <i>ao</i>. ἠκολούθησα, <i>pf. inus</i>.)</font> <font color=\"brown\">[ᾰ]</font> :<br><b>   I</b> faire route avec, accompagner, suivre, <i>p. opp. à</i> ἡγοῦμαι <i>ou à</i> ἄρχομαι, PLAT. <i>Rsp. 474</i> c ; PLUT. <i>Popl. c. Sol. 3, M. 1008</i> b ; ἀκ. τινι, ATT. (AR. <i>Pl. 19 ;</i> LUC. <i>D. deor. 20, 3, etc.) ; rar</i>. τινα, MÉN. <i>558 Kock ;</i> μετά τινος, ISOCR. <i>299</i> c ; DÉM. <i>608, 14 ;</i> σύν τινι, XÉN. <i>An. 7, 5, 3 ;</i> κατόπιν τινός, AR. <i>Pl. 13,</i> suivre qqn, marcher à la suite de qqn, accompagner qqn ; <i>en parl. de serviteurs,</i> TH. <i>Char. 18, 2 ;</i> PALÆPH. <i>2, 4 ;</i> οἱ ἀκολουθοῦντες, PLUT. <i>Alc. 3,</i> la suite (de qqn) ; <i>voc</i>. ἀκολουθῶν, MÉN. (ATH. <i>639</i> d) esclave ! garçon ! <i>avec une prép. et le rég. du lieu :</i> ἀκ. εἰς, DÉM. <i>53, 25 Baiter-Sauppe ;</i> ἐπί, DÉM. <i>47, 51, etc. ;</i> πρός, DÉM. <i>60, 13, etc</i>. suivre <i>ou</i> accompagner jusqu’à, vers, <i>etc. ;</i><br><b>   II</b> <i>fig. ou p. anal. :</i><br><b> 1</b> suivre par l’intelligence ; ἀ. τῷ λόγῳ, PLAT. <i>Phæd. 107</i> b, <i>etc</i>. suivre le développement d’un discours, le comprendre ;<br><b> 2</b> se laisser conduire <i>ou</i> diriger par : ἀ. τῇ γνώμῃ τινός, THC. <i>3, 38,</i> suivre l’avis de qqn ; ἀ. τοῖς καιροῖς, DÉM. <i>730, 18,</i> obéir aux circonstances ; ἀ. τοῖς νόμοις, AND. <i>31, 35,</i> obéir aux lois ;<br><b> 3</b> suivre l’exemple de, se modeler sur (qqn <i>ou</i> qqe ch.) LUC. <i>J. voc. 12 ;</i><br><b> 4</b> être la suite naturelle de, être conséquent avec <i>ou</i> conforme à, <i>dat</i>. PLAT. <i>Rsp. 332</i> d, <i>400</i> e, <i>etc. ; impers</i>. ἀκολουθεῖ, ARSTT. <i>Categ. 12, 2,</i> il suit de là ;<br><b> 5</b> être analogue <i>ou</i> semblable à, <i>dat</i>. ARSTT. <i>H.A. 2, 1, 3</i>.<p><b>➼</b> <i>Seul. Com. et Pros. att</i>. — ἀκολουτέω, barbarisme d’un Scythe, AR. <i>Th. 1198</i>.</p><p><b>Étym</b>. ἀκόλουθος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακολουθεω - ἀκολουθέω</font>\n<br><br>vient de  (particule d'union) et keleuthos (une route)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n91 fois dans 88 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (25)</li>\n<li>Marc (18)</li>\n<li>Luc (17)</li>\n<li>Jean (19)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G191":"<h1>akouo</h1>\n<p>Strong n° 191 <i>Prononciation [ak-oo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être doté de la faculté d'entendre, non sourd</li>\n<li>entendre\n<ol type=\"a\">\n<li>considérer ce qui est ou a été dit</li>\n<li>comprendre, percevoir le sens de ce qui est dit</li>\n</ol>\n</li>\n<li>entendre quelque chose\n<ol type=\"a\">\n<li>percevoir par l'oreille ce qui est annoncé devant nous</li>\n<li>apprendre par l'écoute</li>\n<li>quelque chose qui parvient à nos oreilles</li>\n<li>prêter l'oreille à un enseignant</li>\n<li>comprendre, assimiler</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκούω</b> <font color=\"brown\">[ᾰ]</font> <font color=\"darkgreen\">(<i>f</i>. ἀκούσομαι, <i>ao</i>. ἤκουσα, <i>pf</i>. ἀκήκοα, <i>pl.q.pf</i>. ἠκηκόειν, <i>att</i>. ἠκηκόη ; <i>pass. f</i>. ἀκουσθήσομαι, <i>ao</i>. ἠκούσθην, <i>pf. réc</i>. ἤκουσμαι, <i>pl.q.pf. réc</i>. ἠκούσμην)</font><br><b>A</b> entendre :<br><b>   I</b> <i>en gén. avec un gén. de pers</i>. ἀκ. τινός, IL. <i>2, 98, etc. ;</i> OD. <i>1, 370, etc. ;</i> HDT. <i>1, 24 ;</i> ATT. (XÉN. <i>Mem. 2, 6, 31, etc</i>.) entendre qqn ; <i>avec un gén. de pers. accompagné d’un part</i>. ἀκ. τινὸς εἰπόντος, OD. <i>8, 564 ;</i> διαλεγομένου, XÉN. <i>Mem. 2, 4, 1, etc</i>. entendre qqn dire, disserter ; <i>cf</i>. OD. <i>2, 423 ; 8, 95, etc. ; avec un acc. de chose :</i> ἀκ. τι, IL. <i>20, 318, etc. ;</i> OD. <i>3, 94, etc. ;</i> ESCHL. <i>Pr. 740 ;</i> SOPH. <i>El. 1004, etc. ;</i> XÉN. <i>Cyr. 1, 6, 2, etc. ; ou avec un gén. de chose :</i> ἀκ. τινός, IL. <i>22, 447, etc. ;</i> OD. <i>12, 198, etc. ;</i> ESCHL. <i>Eum. 669, etc. ;</i> SOPH. <i>Ph. 225, etc. ;</i> XÉN. <i>Cyr. 3, 1, 8, etc. ;</i> PLAT. <i>Rsp. 450</i> b, <i>etc</i>. entendre qqe ch. ; <i>avec double rég</i>. ἀ. τί τινος, IL. <i>19, 185, etc. ;</i> OD. <i>12, 389 ou</i> τι πρός τινος, IL. <i>6, 524 ;</i> HDT. <i>1, 118 ;</i> SOPH. <i>Aj. 1214 ;</i> τι ἔκ τινος, OD. <i>15, 374 ;</i> HDT. <i>3, 62 ;</i> παρά τινος, PLAT. <i>Rsp. 506</i> d ; ἀπό τινος, THC. <i>1, 125,</i> entendre qqe ch. de la bouche de qqn ; <i>rar</i>. τι ὑπό τινος, XÉN. <i>Œc. 2, 1 ;</i> τινός τινος, OD. <i>17, 115 ;</i> DÉM. <i>228, 12 ; le n. de la pers. ou de la chose au sujet de laquelle on apprend qqe ch. se met au gén. :</i> ἀ. πατρός, OD. <i>4, 114,</i> entendre parler de son père ; <i>en prose, et qqf. en poésie, au gén. précédé d’une prép. :</i> ἀ. περί τινος, OD. <i>19, 270 ;</i> ATT. entendre parler de qqn <i>ou</i> de qqe ch. ; <i>la prop. exprimant l’idée de ce qu’on entend dire de qqn se met, s’il s’agit d’un fait accidentel, au part. ; d’un fait habituel, à l’inf.:</i> εἰ δέ κε τεθνηῶτος ἀκούσῃς, OD. <i>1, 289,</i> si tu apprenais qu’il fût mort ; ἀκούει τοὺς πολεμίους προσιόντας, XÉN. <i>Cyr. 2, 4, 8,</i> il apprend que l’ennemi s’avance ; ἀκούειν αὐτὸν ὄλϐιον εἶναι, IL. <i>24, 543,</i> apprendre qu’il est heureux ;<br><b>   II</b> <i>p. suite :</i><br><b> 1</b> entendre dire, savoir par ouï-dire ; <i>avec</i> ὡς, ὅτι, <i>etc. ou une prop. inf. :</i> Ἀτρείδην δὲ ἀκούετε ὡς ἦλθε, OD. <i>3, 193,</i> vous avez ouï dire comment l’Atride est rentré chez lui (quel a été le retour de l’Atride) ; λέγει ὅτι ἀκήκοε ὡς ἀποθανοῖτο, XÉN. <i>An. 7, 6, 43,</i> il dit qu’il avait entendu dire qu’il serait tué ; ἤκουε καλὸν κἀγαθὸν αὐτὸν εἶναι, XÉN. <i>Cyr. 1, 3, 1,</i> il entendait dire qu’il était parfait ; <i>abs</i>. ἔξοιδ' ἀκούων, SOPH. <i>O.R. 105,</i> je le sais pour l’entendre dire ; εἴ που ἀκούεις, OD. <i>15, 403,</i> peut-être le sais-tu par ouï-dire (<i>lat. fando audire) ; de même dans la locut</i>. ὡς οὕτω γ' ἀκοῦσαι, PLAT. <i>Euthyphr. 3</i> b ; ὥς γε οὑτωσὶ ἀκοῦσαι, PLAT. <i>Lys. 216</i> a, à (les) entendre, <i>càd</i>. sans autre preuve ;<br><b> 2</b> entendre d’ordinaire, <i>càd</i>. être auditeur <i>ou</i> disciple de, suivre les leçons de, <i>gén</i>. DL. <i>2, 3 ;</i><br><b> 3</b> apprendre, <i>en gén.:</i> ἐκ βιϐλίου, PLAT. <i>Phædr. 268</i> c, dans un livre ; <i>abs</i>. οἱ ἀκούοντες, POL. <i>1, 13,</i> les lecteurs ;<br><b> 4</b> entendre, comprendre : κλύοντες οὐκ ἤκουον, ESCHL. <i>Pr. 448,</i> entendant ils ne comprenaient pas ;<br><b>B</b> prêter l’oreille à, écouter, <i>d’où :</i><br><b> 1</b> déférer à, exaucer : τινός, IL. <i>1, 381, etc</i>. qqn ; <i>avec un gén. de chose,</i> ESCHL. <i>Ag. 402 ;</i> EUR. <i>Hipp. 1160,</i> exaucer un souhait, une prière ; <i>rar</i>. τινί, IL. <i>16, 515,</i> exaucer la demande <i>ou</i> la prière de qqn ;<br><b> 2</b> obéir à : τινός, IL. <i>19, 256 ;</i> OD. <i>7, 11 ;</i> ESCHL. <i>Sept. 179 ;</i> HDT. <i>5, 83 ;</i> DÉM. <i>477 ;</i> PLUT. <i>Lyc. 30, etc</i>. obéir à qqn ;<br><b>C</b> entendre parler de soi en bien <i>ou</i> en mal, avoir une réputation bonne <i>ou</i> mauvaise : <i>avec un pron. au sens adv</i>. ἤκουες τάδε, EUR. <i>El. 930,</i> on parlait ainsi de toi ; <i>d’ord. avec un adv</i>. εὖ ἀκούειν, HDT. <i>2, 173, etc. ;</i> PD. <i>P. 1, 192 ;</i> PLAT. <i>Ep. 311</i> c, <i>etc</i>. être loué (<i>cf. lat</i>. bene, male audire) ; ἄμεινον ἀκ. THC. <i>3, 82,</i> recevoir de plus grands éloges ; ἀκ. ἄριστα, HDT. <i>8, 93,</i> recevoir les plus grands éloges ; καλὰ ἀκ. XÉN. <i>Cyr. 7, 1, 13 ;</i> καλῶς ἀκ. MÉN. (STOB. <i>Fl. 15, 1</i>) recevoir des éloges ; κακὰ ἀκ. AR. <i>Th. 388 ;</i> αἰσχρὰ ἀκ. SOPH. <i>Ph. 607 ;</i> κακῶς ἀκ. PLAT. <i>Hipp. ma. 304</i> e ; PLUT. <i>M. 46</i> e ; φλαύρως ἀκ. HDT. <i>7, 10,</i> être décrié <i>ou</i> blâmé ; <i>avec un rég. de pers</i>. ἀκ. πρός τινος κακῶς, HDT. <i>7, 16 ;</i> κακῶς ἀκ. παρά τινι, POL. <i>3, 94 ;</i> PLUT. <i>Cleom. 24 ;</i> κακῶς ἀκ. ὑπό τινος, LYS. <i>8, 15 Baiter-Sauppe,</i> être décrié par qqn ; <i>avec un rég. de cause :</i> κακῶς ἀκ. ἐπί τινι, PLUT. <i>M. 206</i> a, avoir mauvaise réputation à cause de qqn ; ἀκ. οὕτως δεινὸν πρᾶγμα, LYS. <i>118, 8,</i> être accusé d’un crime tellement abominable ; εὖ ἀκ. περί τινος, HDT. <i>6, 86,</i> être loué pour qqe ch. ; <i>avec un adj. servant d’attribut :</i> ἀγαθὸς ἀκούσεαι ἐξ ἀστῶν, THCR. <i>Idyl. 29, 21,</i> tu auras parmi tes concitoyens la réputation d’un homme honnête ; κόλακες καὶ ἐχθροὶ καὶ πάντα ἤκουον, DÉM. <i>18, 46 Baiter-Sauppe,</i> ils s’entendaient appeler flatteurs et ennemis et tout ce qu’on voudra ; κακὸς ἀκούω, SOPH. <i>O.C. 992,</i> je passe pour un méchant, <i>etc. ; qqf. accompagné de l’inf.:</i> ἤκουον εἶναι πρῶτοι, HDT. <i>3, 131,</i> ils passaient pour être les premiers ; <i>cf</i>. PLAT. <i>Lys. 207</i> a ;<br><b>Moy. ἀκούομαι</b> <font color=\"darkgreen\">(<i>impf</i>. ἠκουόμην)</font> entendre, écouter : τινος, IL. <i>4, 331,</i> qqch.<p><b>➼</b> <i>Prés. ind. 3 pl. dor</i>. ἀκούοντι, PD. <i>P. 5, 101 ; inf. épq</i>. ἀκουέμεναι, OD. <i>12, 193, ou</i> ἀκουέμεν, IL. <i>15, 129. Impf</i>. ἄκουον <font color=\"brown\">[ᾰ]</font> IL. <i>12, 442 ;</i> PD. <i>N. 4, 77. Fut. réc</i>. ἀκούσω, LYC. <i>378, 1873 ;</i> DH. <i>5, 57 ;</i> DH. <i>76, 4 ;</i> ANTH. <i>9, 397. Ao</i>. ἄκουσα <font color=\"brown\">[ᾰκ]</font> IL. <i>24, 223 ;</i> PD. <i>N. 2, 14 ; ao. dor</i>. ἄκουσα, <font color=\"brown\">[ᾱκ]</font> PD. <i>P. 9, 112 ;</i> THCR. <i>Idyl. 4, 6. Pf. dor</i>. ἄκουκα, PLUT. <i>Ages. 21. Pl.q.pf. ion</i>. ἀκηκόειν, HDT. <i>2, 52 ; 7, 208. — Pass. pf</i>. ἤκουσμαι, DH. <i>Rhet. 11, 10. Pl.q.pf. sg</i>. ἤκουστο, D. PHAL. <i>217. — Moy. impf. 3 sg</i>. ἀκούετο, IL. <i>4, 331 ; opt. ao. dor</i>. ἀκουσαίμαν, MOSCH. <i>3, 127</i>.</p><p><b>Étym</b>. <i>p</i>. *ἀκουσ-ϳω, <i>de la R. indo-europ</i>. *h²keus-, entendre ; <i>cf. poét</i>. κοέω, <i>lat</i>. caveō, <i>angl</i>. hear.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακουω - ἀκούω</font>\n<br><br>une racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n436 fois dans 399 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (66)</li>\n<li>Marc (48)</li>\n<li>Luc (65)</li>\n<li>Jean (58)</li>\n<li>Actes (89)</li>\n<li>Romains (7)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (5)</li>\n<li>Philippiens (4)</li>\n<li>Colossiens (4)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (4)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (8)</li>\n<li>Jacques (3)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (14)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (46)</li>\n</ul>\n</td></tr>\n</table>","G192":"<h1>akrasia</h1>\n<p>Strong n° 192 <i>Prononciation [ak-ras-ee'-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>manque d'auto-contrôle, incontinence, intempérance, avidité, dérèglement, insatiable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nἀκρασία² <b>ας (ἡ)</b> :<br><i>c.</i> ἀκράτεια.<br><i><b><font color=\"red\">Ant.</font></b></i> σωφροσύνη, ἐγκράτεια.<br><i><b><font color=\"darkorange\">Par.</font></b></i> πλεονεξία, ἀκοσμία.<br>ἀκρασία¹ <b>ας (ἡ)</b> :<br>intempérie.<br><i><b><font color=\"brown\">Étym.</font></b></i> ἄκρατος.<br><i><b><font color=\"red\">Ant.</font></b></i> εὐκρασία.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κρασια - ἀκρασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G193":"<h1>akrates</h1>\n<p>Strong n° 193 <i>Prononciation [ak-rat'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans auto-contrôle, sans tempérance, incontinent, non maître de soi, déréglé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκρατής</b> <b>ἀ·κρατής, ής, ές</b> <font color=\"brown\">[ᾰτ]</font> :<br><b>   I</b> <i>abs</i>. sans force : γῆρας ἀ. SOPH. <i>O.C. 1236,</i> vieillesse débile ;<br><b>   II</b> <i>avec un rég. :</i><br><b> 1</b> qui n’est pas maître de : ἀ. σκελῶν, χειρῶν, HPC. <i>816</i> c, <i>etc</i>. qui n’a pas le libre usage de ses jambes, de ses mains, <i>en parl. d’un malade ;</i><br><b> 2</b> qui ne se contient pas, intempérant : ἀ. γλώσσης, ESCHL. <i>Pr. 884,</i> qui n’est plus maître de sa langue, qui parle au hasard ; ἀ. οἴνου, XÉN. <i>Œc. 12, 11,</i> qui use du vin avec excès ; ἀ. κέρδους, τιμῆς, ARSTT. <i>Nic. 7, 1, 7,</i> avide de gain, d’honneurs ; <i>avec une prép</i>. ἀ. πρός τι, ARSTT. <i>H.A. 8, 4, 2 ;</i> περί τι, ARSTT. <i>P.A. 4, 11, 5,</i> intempérant dans l’usage de qqe ch. ; <i>avec un inf</i>. ἀ. εἵργεσθαί τινος, PLAT. <i>Soph. 252</i> c, incapable de se retenir de qqe ch. ; <i>abs</i>. στόμα ἀκρατές, AR. <i>Ran. 837,</i> langue (<i>litt</i>. bouche) déréglée ; ἀ. ὀργή, PLUT. <i>M. 10</i> e, colère qui ne se contient pas.<p><b>Étym</b>. ἀ, κράτος.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κρατης - ἀκρατής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G194":"<h1>akratos</h1>\n<p>Strong n° 194 <i>Prononciation [ak'-rat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non mélangé, pur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄκρατος</b> <b>ἄ·κρατος, ος, ον</b> <font color=\"brown\">[ᾱτ]</font> :<br><b>   I</b> non mélangé, pur : ἄ. οἶνος, OD. <i>24, 73 ;</i> HDT. <i>1, 207 ;</i> XÉN. <i>An. 4, 5, 27, etc</i>. vin pur ; <i>subst</i>. ὁ ἄ. AR. <i>Eq. 105, etc. ;</i> τὸ ἄ. ARSTT. <i>Poet. 25, 16 ;</i> ATH. <i>441</i> c, <i>m. sign. ;</i> ἄκρητοι (<i>ion</i>.) σπονδαί, IL. <i>2, 341,</i> libations de vin pur ; ἄκρατα σώματα, PLAT. <i>Tim. 57</i> c, corps purs, <i>càd</i>. simples ; ἄκρατος νοῦς, XÉN. <i>Cyr. 8, 7, 20,</i> pure intelligence ; <i>avec un gén</i>. ἄ. τινος, PLAT. <i>Ax. 370</i> d, pur <i>ou</i> exempt de qqe ch. ;<br><b>   II</b> <i>p. suite,</i> non tempéré, <i>d’où :</i><br><b> 1</b> absolu : ἀ. δικαιοσύνη, PLAT. <i>Rsp. 545</i> a ; ἐλευθερία, PLAT. <i>Rsp. 562</i> d, justice, liberté absolue ; ἄ. νόμος, PLAT. <i>Leg. 723</i> a, loi absolue ;<br><b> 2</b> immodéré, excessif, violent, <i>en parl. de pers. et de choses :</i> ἄκρατος ὀργήν, ESCHL. <i>Pr. 678,</i> violent dans sa colère ; ἄκρατος ὀργή, ALCID. (ARSTT. <i>Rhet. 3, 3, 2</i>) colère violente ; ἵμερος ἄ. SOPH. <i>fr. 678,</i> désir violent.<br><i>● Cp</i>. ἀκρατέστερος, HYPÉR. (ATH. <i>424</i> d) ; ARSTT. <i>Probl. 3, 3 ; postér</i>. ἀκρατότερος, PLUT. <i>M. 677</i> c. <i>● Sup</i>. ἀκρατέστατος, PLAT. <i>Phil. 53</i> a, <i>etc</i>.<p><b>➼</b> <i>Ion</i>. ἄκρητος, HOM. HDT. <i>ll. cc. ; cp</i>. ἀκρητέστερος, HPC. <i>Progn. 41, 7 ;</i> <i>● Sup</i>. -έστατος, HPC. <i>1010</i> f.</p><p><b>Étym</b>. ἀ, κεράννυμι.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-κρατος - ἄκρατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G195":"<h1>akribeia</h1>\n<p>Strong n° 195 <i>Prononciation [ak-ree'-bi-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>exactement, en strict accord avec la rigueur de la loi Mosaïque, respect scrupuleux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκρίβεια</b> <b>ας (ἡ)</b> <font color=\"brown\">[ῑ]</font> :<br><b> 1</b> exactitude, soin minutieux, THC. <i>1, 22 ;</i> ANT. <i>127, 12, etc. ;</i> δι' ἀκριϐείας, PLAT. <i>Tim. 23</i> d, <i>etc. ;</i> διὰ πάσης ἀκριϐείας, PLAT. <i>Leg. 876</i> c ; εἰς ἀκρίϐειαν, PLAT. <i>Euthyd. 288</i> a ; ARSTT. <i>Pol. 7, 11, 9 ;</i> εἰς τὴν ἀκρίϐειαν, PLAT. <i>Gorg. 487</i> c ; πρὸς ἀκρίϐειαν, ARSTT. <i>Respir. 16 ;</i> πρὸς τὴν ἀκρίϐειαν, PLAT. <i>Leg. 769</i> d ; πάσῃ ἀκριϐείᾳ, PLAT. <i>Phædr. 271</i> a, en toute rigueur, exactement, avec précision ; <i>p. suite,</i> ἀ. τοῦ ναυτικοῦ, THC. <i>7, 13,</i> exacte discipline dans la flotte ; ἀ. νόμων, ISOCR. <i>147</i> e, rigueur des lois ;<br><b> 2</b> <i>en parl. de dépenses,</i> économie rigide, PLUT. <i>Per. 16 ; d’où</i> δι' ἀκριϐείας ἐστί τί τινι, PLAT. <i>Leg. 844</i> b, on mesure qqe ch. parcimonieusement à qqn ;<br><b> 3</b> <i>en mauv. part,</i> précision excessive, POL. <i>32, 13, 11 ; plur</i>. minuties, PLAT. <i>Rsp. 504</i> e.<p><b>Étym</b>. ἀκριϐής.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακριβεια - ἀκρίβεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G196":"<h1>akribestatos</h1>\n<p>Strong n° 196 <i>Prononciation [ak-ree-bes'-ta-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>exact, soigneux</li>\n<li>dans une secte stricte : l'interprétation la plus précise et la plus rigoureuse de la loi Mosaïque, l'observation des moindres préceptes de la loi et de la tradition</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nVenant de : <b>ἀκριϐής, </b><b>ής, ές</b> <span>[ῑ]</span> exact :<br><b>   I</b> <i>en parl. de pers. et de ch. :</i><br><b>      1</b> exact, sûr : ἀκριϐὴς ὄμμασι, THCR. <i>Idyl. 22, 194,</i> (Lyncée) aux yeux perçants ; οὐκ ἔστ' ἀκριϐὲς οὐδὲν εἰς εὐανδρίαν, EUR. <i>El. 367,</i> il n’y a point d’indice certain de la valeur d’un homme ;<br><b>      2</b> scrupuleux, consciencieux (juge, THC. <i>3, 46 ;</i> médecin, PLAT. <i>Rsp. 342</i> d, <i>etc.) ; avec une nuance de blâme,</i> exact à l’excès, pointilleux, minutieux, PLAT. <i>Leg. 762</i> d ;<br><b>   II</b> <i>en parl. de choses :</i><br><b>      1</b> qui s’adapte exactement, qui va bien (cuirasse) XÉN. <i>Mem. 3, 10, 15 ;</i><br><b>      2</b> bien réglé, régulier (régime) HPC. <i>Aph. 1243 ;</i> οὐκ εἰς ἀκριϐὲς ἦλθες, EUR. <i>Tr. 901,</i> (la décision sur ton sort) n’a pas abouti à un jugement régulier (néanmoins l’armée me charge de te tuer) ;<br><b>      3</b> qui se produit au moment précis, HPC. <i>Epid. 1, 943 ;</i><br><b>      4</b> exact, précis, rigoureux (raisonnement, argument, <i>etc</i>.) AR. <i>Nub. 130 ;</i> PLAT. <i>Rsp. 341</i> c ; DH. <i>Is. 20, etc. ;</i> ἐς τὸ ἀκριϐὲς εἰπεῖν, THC. <i>6, 82,</i> pour parler exactement.<br><span>•<i> Cp</i>. -έστερος, PLAT. <i>Hipp. ma. 295</i> a, <i>Leg. 965</i> b, <i>etc. ;</i> <i>• Sup</i>. -έστατος, XÉN. <i>Œc. 8, 11 ;</i> PLAT. <i>Rsp. 503</i> b, <i>Phæd. 58</i> d, <i>etc</i>.<br><span><b>Étym</b>. <i>p.-ê. de</i> ἄκρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακριβηστατος - ἀκριβήστατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G197":"<h1>akribesteron</h1>\n<p>Strong n° 197 <i>Prononciation [ak-ree-bes'-ter-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>plus exactement, plus parfaitement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nVenant de : <b>ἀκριϐής, </b><b>ής, ές</b> <span>[ῑ]</span> exact :<br><b>   I</b> <i>en parl. de pers. et de ch. :</i><br><b>      1</b> exact, sûr : ἀκριϐὴς ὄμμασι, THCR. <i>Idyl. 22, 194,</i> (Lyncée) aux yeux perçants ; οὐκ ἔστ' ἀκριϐὲς οὐδὲν εἰς εὐανδρίαν, EUR. <i>El. 367,</i> il n’y a point d’indice certain de la valeur d’un homme ;<br><b>      2</b> scrupuleux, consciencieux (juge, THC. <i>3, 46 ;</i> médecin, PLAT. <i>Rsp. 342</i> d, <i>etc.) ; avec une nuance de blâme,</i> exact à l’excès, pointilleux, minutieux, PLAT. <i>Leg. 762</i> d ;<br><b>   II</b> <i>en parl. de choses :</i><br><b>      1</b> qui s’adapte exactement, qui va bien (cuirasse) XÉN. <i>Mem. 3, 10, 15 ;</i><br><b>      2</b> bien réglé, régulier (régime) HPC. <i>Aph. 1243 ;</i> οὐκ εἰς ἀκριϐὲς ἦλθες, EUR. <i>Tr. 901,</i> (la décision sur ton sort) n’a pas abouti à un jugement régulier (néanmoins l’armée me charge de te tuer) ;<br><b>      3</b> qui se produit au moment précis, HPC. <i>Epid. 1, 943 ;</i><br><b>      4</b> exact, précis, rigoureux (raisonnement, argument, <i>etc</i>.) AR. <i>Nub. 130 ;</i> PLAT. <i>Rsp. 341</i> c ; DH. <i>Is. 20, etc. ;</i> ἐς τὸ ἀκριϐὲς εἰπεῖν, THC. <i>6, 82,</i> pour parler exactement.<br><span>•<i> Cp</i>. -έστερος, PLAT. <i>Hipp. ma. 295</i> a, <i>Leg. 965</i> b, <i>etc. ;</i> <i>• Sup</i>. -έστατος, XÉN. <i>Œc. 8, 11 ;</i> PLAT. <i>Rsp. 503</i> b, <i>Phæd. 58</i> d, <i>etc</i>.<br><span><b>Étym</b>. <i>p.-ê. de</i> ἄκρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακριβηστερον - ἀκριβέστερον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (4)</li>\n</ul>\n</td></tr>\n</table>","G198":"<h1>akriboo</h1>\n<p>Strong n° 198 <i>Prononciation [ak-ree-bo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>savoir précisément, faire exactement, mener à bonne fin, s'acquitter de son travail,</li>\n<li>faire des recherches soigneuses, savoir exactement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκριβόω</b> <b>ἀκριϐόω-ῶ</b> <font color=\"darkgreen\">(<i>f</i>. ώσω, <i>ao</i>. ἠκρίϐωσα, <i>pf</i>. ἠκρίϐωκα)</font> <font color=\"brown\">[ῑ]</font> être exact, <i>d’où :</i><br><b> 1</b> faire exactement, bien arranger, mener à bonne fin : τι, EUR. <i>Hipp. 469,</i> qqe ch. ; τὰς τάξεις, XÉN. <i>Cyr. 2, 1, 13,</i> garder exactement les rangs ; πάντα, XÉN. <i>Cyr. 2, 2, 2 ; 2, 3, 5,</i> supporter avec constance toutes les fatigues ; <i>au pass</i>. être exact <i>ou</i> parfait, AR. <i>Ran. 1483 ;</i> ARSTT. <i>Pol. 3, 7, 4 ;</i><br><b> 2</b> savoir exactement, <i>acc</i>. XÉN. <i>Cyr. 2, 2, 9 ;</i> PLAT. <i>Charm. 156</i> a, <i>etc. ;</i><br><b> 3</b> répondre exactement à, correspondre parfaitement à, ARSTT. <i>Meteor. 2, 6, 9, etc. ;</i><br><b> 4</b> inventer des procédés subtils (de discussion) EUR. <i>Hec. 1192</i>.<p><b>Étym</b>. ἀκριϐής.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακριβοω - ἀκριβόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G199":"<h1>akribos</h1>\n<p>Strong n° 199 <i>Prononciation [ak-ree-boce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol><li>exactement, précisément, soigneusement, scrupuleusement, consciencieusement</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀκριβῶς</b> <font color=\"brown\">[ῑ]</font> <i>adv. :</i><br><b> 1</b> exactement : ἀ. εἰδέναι, ἐπίστασθαι, HDT. <i>7, 32 ;</i> ESCHL. <i>Pr. 328 ;</i> ISOCR. <i>91</i> d, savoir exactement, avec précision ; ἀ. τίθεσθαι, EUR. <i>Med. 532,</i> traiter un sujet rigoureusement ; <i>d’où avec un adj</i>. absolument, tout à fait, <i>au sens d’une sorte de superl. ajouté à l’adj</i>. ESCHL. <i>Pr. 328 ;</i><br><b> 2</b> péniblement : ἀ. καὶ μόλις, PLUT. <i>Alex. 16,</i> avec de grandes difficultés ;<br><b> 3</b> avec une économie rigoureuse, AND. <i>33, 19</i>.<br><i>● Cp</i>. ἀκριϐέστερον, THC. <i>6, 55 ;</i> PLAT. <i>Rsp. 491</i> c. <i>● Sup</i>. ἀκριϐέστατα, THC. <i>6, 91 ;</i> PLAT. <i>Phæd. 58</i> d, <i>etc</i>.<p><b>Étym</b>. ἀκριϐής.</p>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ακριβως - ἀκριβῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>"};
